  input  logic [DATA_W-1:0]      trace_desc_wdata,

  // Response out
  output logic                   resp_valid,
  input  logic                   resp_ready,
  output logic [DATA_W-1:0]      resp_rdata,
  output logic                   resp_hit,
  output logic                   resp_approx,

  // External memory interface
