  localparam integer CMDQ_PREF_BLOCK_TH = (CMDQ_DEPTH <= 1) ? 1 : (CMDQ_DEPTH - 1);
  logic [CMDQ_W-1:0]    cmdq_level;

  kcmu_decoder #(
    .ADDR_W(ADDR_W),
    .DATA_W(DATA_W),
    .SCORE_W(SCORE_W)
  ) u_dec (
    .trace_valid(trace_valid),
    .trace_ready(trace_ready),
    .trace_op(trace_op),
    .trace_addr(trace_addr),
    .trace_wdata(trace_wdata),
    .trace_meta_valid(trace_meta_valid),
    .trace_seq_id(trace_seq_id),
    .trace_phase(trace_phase),
    .trace_kv_kind(trace_kv_kind),
    .trace_layer(trace_layer),
    .trace_head(trace_head),
    .trace_token(trace_token),
    .trace_prio(trace_prio),

    .cmd_valid(dec_cmd_valid),
    .cmd_ready(dec_cmd_ready),
    .cmd_op(dec_cmd_op),
    .cmd_addr(dec_cmd_addr),
    .cmd_wdata(dec_cmd_wdata),
