    .cmd_token_block_id(dec_cmd_token_block_id),
    .cmd_attn_epoch(dec_cmd_attn_epoch)
  );

  kcmu_trace_desc_expander #(
    .ADDR_W(ADDR_W),
    .DATA_W(DATA_W),
    .SCORE_W(SCORE_W)
  ) u_desc_exp (
    .clk(clk),
    .rst_n(rst_n),
    .desc_valid(trace_desc_valid),
