  assign front_cmd_valid = desc_cmd_valid | dec_cmd_valid;
  assign front_cmd_op = desc_cmd_valid ? desc_cmd_op : dec_cmd_op;
  assign front_cmd_addr = desc_cmd_valid ? desc_cmd_addr : dec_cmd_addr;
  assign front_cmd_wdata = desc_cmd_valid ? desc_cmd_wdata : dec_cmd_wdata;
