  assign front_cmd_seq_id = desc_cmd_valid ? desc_cmd_seq_id : dec_cmd_seq_id;
  assign front_cmd_phase = desc_cmd_valid ? desc_cmd_phase : dec_cmd_phase;
  assign front_cmd_kv_kind = desc_cmd_valid ? desc_cmd_kv_kind : dec_cmd_kv_kind;
