  assign front_cmd_compression_risk = desc_cmd_valid ? desc_cmd_compression_risk : {kcmu_pkg::KCMU_COST_CLASS_W{1'b0}};
  assign front_cmd_spill_cost = desc_cmd_valid ? desc_cmd_spill_cost : {kcmu_pkg::KCMU_COST_CLASS_W{1'b0}};
  assign front_cmd_service_criticality = desc_cmd_valid ? desc_cmd_service_criticality : {SCORE_W{1'b0}};
  assign front_cmd_policy_select_s5 = desc_cmd_valid ? desc_cmd_policy_select_s5 : 1'b1;
  assign front_cmd_temporal_persist_class = desc_cmd_valid ? desc_cmd_temporal_persist_class : {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
  assign front_cmd_reuse_distance_class = desc_cmd_valid ? desc_cmd_reuse_distance_class : {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
  assign front_cmd_query_structure_class = desc_cmd_valid ? desc_cmd_query_structure_class : {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
  assign front_cmd_sched_urgency_hint = desc_cmd_valid ? desc_cmd_sched_urgency_hint : {kcmu_pkg::KCMU_SCHED_HINT_W{1'b0}};
  assign front_cmd_sig_valid = desc_cmd_valid ? desc_cmd_sig_valid : 1'b0;
  assign front_cmd_query_sig = desc_cmd_valid ? desc_cmd_query_sig : 6'd0;
  assign front_cmd_key_sig = desc_cmd_valid ? desc_cmd_key_sig : 6'd0;
  assign front_cmd_prefix_class = desc_cmd_valid ? desc_cmd_prefix_class : 2'd0;
  assign front_cmd_router_class = desc_cmd_valid ? desc_cmd_router_class : 2'd0;
  assign front_cmd_block_last = desc_cmd_valid ? desc_cmd_block_last : 1'b1;
  assign desc_cmd_ready = front_cmd_ready;
  assign dec_cmd_ready = front_cmd_ready && !desc_cmd_valid;

  kcmu_cmd_queue #(
    .ADDR_W(ADDR_W),
    .DATA_W(DATA_W),
    .SCORE_W(SCORE_W),
    .DEPTH(CMDQ_DEPTH),
    .LOOKAHEAD_TARGET_EN(CMDQ_LOOKAHEAD_GROUP_TARGET_EN),
    .LOOKAHEAD_MAX_DELTA(CMDQ_LOOKAHEAD_MAX_DELTA),
    .DESC_TARGET_EN(CMDQ_DESCRIPTOR_GROUP_TARGET_EN),
    .DESC_TARGET_DELTA(CMDQ_DESCRIPTOR_GROUP_TARGET_DELTA),
    .DESC_TARGET_ADAPTIVE_EN(CMDQ_DESCRIPTOR_GROUP_TARGET_ADAPTIVE_EN),
    .DESC_TARGET_HIGH_DELTA(CMDQ_DESCRIPTOR_GROUP_TARGET_HIGH_DELTA),
    .DESC_TARGET_DENSITY_TH(CMDQ_DESCRIPTOR_GROUP_TARGET_DENSITY_TH),
    .L1_LINES(LINES),
    .L2_LINES(L2_LINES),
    .VB_LINES(L2_VB_LINES),
    .GROUP_BUF_LINES(L2_GROUP_BUF_LINES)
  ) u_cmdq (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(front_cmd_valid),
    .in_ready(front_cmd_ready),
    .in_op(front_cmd_op),
    .in_addr(front_cmd_addr),
    .in_wdata(front_cmd_wdata),
    .in_meta_valid(front_cmd_meta_valid),
    .in_seq_id(front_cmd_seq_id),
    .in_phase(front_cmd_phase),
    .in_kv_kind(front_cmd_kv_kind),
    .in_layer(front_cmd_layer),
    .in_head(front_cmd_head),
    .in_token(front_cmd_token),
    .in_prio(front_cmd_prio),
    .in_score(front_cmd_score),
    .in_attn_valid(front_cmd_attn_valid),
    .in_attn_score(front_cmd_attn_score),
    .in_recent_rank(front_cmd_recent_rank),
    .in_token_block_id(front_cmd_token_block_id),
    .in_attn_epoch(front_cmd_attn_epoch),
    .in_head_budget_class(front_cmd_head_budget_class),
    .in_query_relevance(front_cmd_query_relevance),
    .in_compression_risk(front_cmd_compression_risk),
    .in_spill_cost(front_cmd_spill_cost),
    .in_service_criticality(front_cmd_service_criticality),
    .in_policy_select_s5(front_cmd_policy_select_s5),
    .in_temporal_persist_class(front_cmd_temporal_persist_class),
    .in_reuse_distance_class(front_cmd_reuse_distance_class),
    .in_query_structure_class(front_cmd_query_structure_class),
    .in_sched_urgency_hint(front_cmd_sched_urgency_hint),
    .in_sig_valid(front_cmd_sig_valid),
    .in_query_sig(front_cmd_query_sig),
    .in_key_sig(front_cmd_key_sig),
    .in_prefix_class(front_cmd_prefix_class),
    .in_router_class(front_cmd_router_class),
    .in_block_last(front_cmd_block_last),
    .out_valid(cmdq_valid),
    .out_ready(cmdq_ready),
    .out_op(cmdq_op),
    .out_addr(cmdq_addr),
    .out_wdata(cmdq_wdata),
    .out_meta_valid(cmdq_meta_valid),
    .out_seq_id(cmdq_seq_id),
    .out_phase(cmdq_phase),
    .out_kv_kind(cmdq_kv_kind),
    .out_layer(cmdq_layer),
    .out_head(cmdq_head),
    .out_token(cmdq_token),
    .out_prio(cmdq_prio),
    .out_score(cmdq_score),
    .out_attn_valid(cmdq_attn_valid),
    .out_attn_score(cmdq_attn_score),
    .out_recent_rank(cmdq_recent_rank),
    .out_token_block_id(cmdq_token_block_id),
    .out_attn_epoch(cmdq_attn_epoch),
    .out_head_budget_class(cmdq_head_budget_class),
    .out_query_relevance(cmdq_query_relevance),
    .out_compression_risk(cmdq_compression_risk),
    .out_spill_cost(cmdq_spill_cost),
    .out_service_criticality(cmdq_service_criticality),
    .out_policy_select_s5(cmdq_policy_select_s5),
    .out_temporal_persist_class(cmdq_temporal_persist_class),
    .out_reuse_distance_class(cmdq_reuse_distance_class),
    .out_query_structure_class(cmdq_query_structure_class),
    .out_sched_urgency_hint(cmdq_sched_urgency_hint),
    .out_sig_valid(cmdq_sig_valid),
    .out_query_sig(cmdq_query_sig),
    .out_key_sig(cmdq_key_sig),
    .out_prefix_class(cmdq_prefix_class),
    .out_router_class(cmdq_router_class),
    .out_block_last(cmdq_block_last),
    .out_group_target_valid(cmdq_group_target_valid),
    .out_group_target_addr(cmdq_group_target_addr),
    .q_level(cmdq_level)
  );

  // Insert a registered command slice after cmdq to cut long cmdq->policy/kv/pf timing arcs.
  assign cmdq_ready = !cmd_valid || cmd_ready;

  always @(posedge clk) begin
    if (!rst_n) begin
      cmd_valid <= 1'b0;
      cmd_op <= KCMU_OP_RD;
      cmd_addr <= {ADDR_W{1'b0}};
      cmd_wdata <= {DATA_W{1'b0}};
      cmd_meta_valid <= 1'b0;
      cmd_seq_id <= {kcmu_pkg::KCMU_SEQ_W{1'b0}};
      cmd_phase <= kcmu_pkg::KCMU_PHASE_PREFILL;
      cmd_kv_kind <= kcmu_pkg::KCMU_KV_KIND_K;
      cmd_layer <= 3'd0;
      cmd_head <= 2'd0;
      cmd_token <= 12'd0;
      cmd_prio <= 3'd0;
      cmd_score <= {SCORE_W{1'b0}};
      cmd_attn_valid <= 1'b0;
      cmd_attn_score <= {SCORE_W{1'b0}};
      cmd_recent_rank <= {kcmu_pkg::KCMU_ATTN_RANK_W{1'b0}};
      cmd_token_block_id <= {kcmu_pkg::KCMU_TOKEN_BLOCK_W{1'b0}};
      cmd_attn_epoch <= {kcmu_pkg::KCMU_ATTN_EPOCH_W{1'b0}};
      cmd_head_budget_class <= {kcmu_pkg::KCMU_HEAD_BUDGET_W{1'b0}};
      cmd_query_relevance <= {SCORE_W{1'b0}};
      cmd_compression_risk <= {kcmu_pkg::KCMU_COST_CLASS_W{1'b0}};
      cmd_spill_cost <= {kcmu_pkg::KCMU_COST_CLASS_W{1'b0}};
      cmd_service_criticality <= {SCORE_W{1'b0}};
      cmd_policy_select_s5 <= 1'b1;
      cmd_temporal_persist_class <= {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
      cmd_reuse_distance_class <= {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
      cmd_query_structure_class <= {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}};
      cmd_sched_urgency_hint <= {kcmu_pkg::KCMU_SCHED_HINT_W{1'b0}};
      cmd_sig_valid <= 1'b0;
      cmd_query_sig <= 6'd0;
      cmd_key_sig <= 6'd0;
      cmd_prefix_class <= 2'd0;
      cmd_router_class <= 2'd0;
      cmd_block_last <= 1'b1;
      cmd_group_target_valid <= 1'b0;
      cmd_group_target_addr <= {ADDR_W{1'b0}};
    end else if (cmdq_ready && cmdq_valid) begin
      cmd_valid <= 1'b1;
      cmd_op <= cmdq_op;
      cmd_addr <= cmdq_addr;
      cmd_wdata <= cmdq_wdata;
      cmd_meta_valid <= cmdq_meta_valid;
      cmd_seq_id <= cmdq_seq_id;
      cmd_phase <= cmdq_phase;
      cmd_kv_kind <= cmdq_kv_kind;
      cmd_layer <= cmdq_layer;
      cmd_head <= cmdq_head;
      cmd_token <= cmdq_token;
      cmd_prio <= cmdq_prio;
      cmd_score <= cmdq_score;
      cmd_attn_valid <= cmdq_attn_valid;
      cmd_attn_score <= cmdq_attn_score;
      cmd_recent_rank <= cmdq_recent_rank;
      cmd_token_block_id <= cmdq_token_block_id;
      cmd_attn_epoch <= cmdq_attn_epoch;
      cmd_head_budget_class <= cmdq_head_budget_class;
      cmd_query_relevance <= cmdq_query_relevance;
      cmd_compression_risk <= cmdq_compression_risk;
      cmd_spill_cost <= cmdq_spill_cost;
      cmd_service_criticality <= cmdq_service_criticality;
      cmd_policy_select_s5 <= cmdq_policy_select_s5;
      cmd_temporal_persist_class <= cmdq_temporal_persist_class;
      cmd_reuse_distance_class <= cmdq_reuse_distance_class;
      cmd_query_structure_class <= cmdq_query_structure_class;
      cmd_sched_urgency_hint <= cmdq_sched_urgency_hint;
      cmd_sig_valid <= cmdq_sig_valid;
      cmd_query_sig <= cmdq_query_sig;
      cmd_key_sig <= cmdq_key_sig;
      cmd_prefix_class <= cmdq_prefix_class;
      cmd_router_class <= cmdq_router_class;
      cmd_block_last <= cmdq_block_last;
      cmd_group_target_valid <= cmdq_group_target_valid;
      cmd_group_target_addr <= cmdq_group_target_addr;
    end else if (cmd_ready && cmd_valid) begin
      cmd_valid <= 1'b0;
    end
  end

  // Prefetcher / scheduler / KV mapper
  wire cmd_fire = cmd_valid && cmd_ready;
  wire cmd_fire_read = cmd_fire && (cmd_op == KCMU_OP_RD);
  wire cmd_fire_write = cmd_fire && (cmd_op == KCMU_OP_WR);
`ifdef KCMU_V409_DEBUG
  always_ff @(posedge clk) begin
    if (rst_n) begin
      if (front_cmd_valid && front_cmd_ready &&
          (front_cmd_addr >= ADDR_W'(48)) && (front_cmd_addr <= ADDR_W'(120))) begin
        $display("V409_MCU_FRONT addr=%0d op=%0d block_last=%0d qlevel=%0d cmd_valid=%0d cmd_ready=%0d time=%0t",
                 front_cmd_addr,
                 front_cmd_op,
                 front_cmd_block_last,
                 cmdq_level,
                 cmd_valid,
                 cmd_ready,
                 $time);
      end
      if (cmdq_valid && cmdq_ready &&
          (cmdq_addr >= ADDR_W'(48)) && (cmdq_addr <= ADDR_W'(120))) begin
        $display("V409_MCU_CMDQ_OUT addr=%0d op=%0d block_last=%0d target_valid=%0d target=%0d qlevel=%0d cmd_valid=%0d cmd_ready=%0d time=%0t",
                 cmdq_addr,
                 cmdq_op,
                 cmdq_block_last,
                 cmdq_group_target_valid,
                 cmdq_group_target_addr,
                 cmdq_level,
                 cmd_valid,
                 cmd_ready,
                 $time);
      end
      if (cmd_fire &&
          (cmd_addr >= ADDR_W'(48)) && (cmd_addr <= ADDR_W'(120))) begin
        $display("V409_MCU_FIRE addr=%0d phys=%0d op=%0d block_last=%0d target_valid=%0d target=%0d map_hit=%0d map_alloc=%0d time=%0t",
                 cmd_addr,
                 cmd_addr_exec,
                 cmd_op,
                 cmd_block_last,
                 cmd_group_target_valid,
                 cmd_group_target_addr,
                 kv_map_hit,
                 kv_map_alloc,
                 $time);
      end
    end
  end
`endif
  logic [2:0] cmd_base_qos;
  logic [2:0] cmd_sched_qos;
  logic [2:0] cmd_qos;
  logic [2:0] cmd_exec_qos;
  logic [2:0] pf_qos;
  logic [2:0] true_h2o_pf_miss_credit;
  logic [2:0] true_h2o_pf_useful_credit;
  logic [4:0] true_h2o_pf_budget_read_cnt;
  logic [2:0] true_h2o_pf_budget_issue_cnt;
  logic [5:0] true_h2o_pf_phase_read_cnt;
  logic [7:0] true_h2o_pf_phase_write_cnt;
  logic [4:0] true_h2o_pf_phase_hhonly_cnt;
  wire        true_h2o_pf_miss_credit_gate_active =
    TRUE_H2O_MISS_CREDIT_PREFETCH_EN || TRUE_H2O_STRICT_MISS_CREDIT_PREFETCH_EN;
  wire        true_h2o_pf_miss_credit_ok =
    !true_h2o_pf_miss_credit_gate_active ? 1'b1 :
    TRUE_H2O_STRICT_MISS_CREDIT_PREFETCH_EN ? (true_h2o_pf_miss_credit >= 3'd4) :
    (true_h2o_pf_miss_credit != 3'd0);
  wire        true_h2o_pf_budget_ok =
    !TRUE_H2O_PREFETCH_BUDGET_EN || (true_h2o_pf_budget_issue_cnt < TRUE_H2O_PREFETCH_EPOCH_BUDGET);
  wire        true_h2o_pf_budget_epoch_wrap =
    TRUE_H2O_PREFETCH_BUDGET_EN && cmd_fire_read && (true_h2o_pf_budget_read_cnt == 5'd31);
  wire        true_h2o_pf_wrdom_hhonly_gate_ok =
    !TRUE_H2O_PREFETCH_WRDOM_HHONLY_GATE_EN ||
    ((true_h2o_pf_phase_read_cnt >= 6'd8) &&
     (true_h2o_pf_phase_write_cnt >= ({2'b00, true_h2o_pf_phase_read_cnt} << 2)) &&
     (true_h2o_pf_phase_hhonly_cnt >= TRUE_H2O_PREFETCH_WRDOM_HHONLY_TH));
  logic [2:0] last_read_qos;
  logic       cmd_sem_hot;
  logic       cmd_sem_cold;
  logic       last_read_sem_hot;
  logic       last_read_fill_allow;
  logic       last_read_victim_protect;
  logic       last_read_compress_allow;
  logic       last_read_hh_protect;
  logic       last_read_recent_keep;
  logic [1:0] last_read_h2o_class;
  logic       last_read_backend_critical_hot;
  logic       last_read_backend_critical_warm;
  logic       last_read_backend_critical_qos_boost;
  logic       last_read_backend_critical_fill_effect;
  logic       last_read_backend_critical_protect_effect;
  logic       last_read_backend_critical_prio_raise;
  logic       last_read_backend_critical_cross3;
  logic       last_read_backend_critical_cross4;
  logic       last_read_backend_critical_cross5;
  logic       last_read_backend_critical_fill_mask_sched;
  logic       last_read_backend_critical_fill_mask_prio;
  logic       last_read_backend_critical_fill_mask_budget;
  logic       last_read_backend_critical_protect_mask_sched;
  logic       last_read_backend_critical_protect_mask_guard;
  logic       last_read_backend_critical_protect_mask_prio;
  logic       last_read_h2o_admission_hot;
  logic       last_read_h2o_admission_warm;
  logic       last_read_h2o_admission_qos_boost;
  logic       last_read_h2o_admission_fill_effect;
  logic       last_read_h2o_admission_protect_effect;
  logic       last_read_h2o_admission_fill_mask_sched;
  logic       last_read_h2o_admission_fill_mask_prio;
  logic       last_read_h2o_admission_fill_mask_budget;
  logic       last_read_h2o_admission_protect_mask_sched;
  logic       last_read_h2o_admission_protect_mask_guard;
  logic       last_read_h2o_admission_protect_mask_prio;
  logic       last_read_service_fill_rescue;
  logic       last_read_service_issue_sched_bridge;
  logic       last_read_service_issue_boost;
