  logic       last_read_fill_allow_no_backend_critical;
  logic       last_read_policy_select_s5;
  logic       last_read_h2o_search_l2_miss_heavy;
  logic       last_read_h2o_search_meta_guard;
  logic       last_read_h2o_search_floor_guard;
  logic       last_read_h2o_search_retention_guard;
  logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] last_read_reuse_distance_class;
  logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] last_read_query_structure_class;
  logic [kcmu_pkg::KCMU_DESC_CLASS_W-1:0] last_read_temporal_persist_class;
