  wire        true_h2o_pf_useful_credit_ok =
    !TRUE_H2O_PREFETCH_USEFUL_CREDIT_EN ||
    (true_h2o_pf_useful_credit >= 3'd2) ||
    (last_read_service_criticality >= SCORE_W'(8'hD0)) ||
    (last_read_query_relevance >= SCORE_W'(8'hC0));
  logic       last_read_kus_adaptive_prefetch_phase;
  logic       last_read_kus_special_prefetch_phase;
  logic       last_read_kus_sliding_prefetch_phase;
  logic       last_read_kus_miss_penalty_prefetch_phase;
