  logic [2:0] kus_kv_struct_streak_cnt;
  logic       cmd_kus_kv_struct_density_ok;
  logic       last_read_kus_prefix_density_ok;
  logic [4:0] kus_special_stream_hold_cnt;
  logic       cmd_kus_special_stream_mode;
  logic       kus_sparse_special_seen;
  logic [ADDR_W-1:0] kus_sparse_special_last_addr;
  logic [2:0] kus_sparse_special_last_gap;
  logic       kus_sparse_special_pf_valid;
  logic       kus_sparse_special_pf_ready;
  logic [ADDR_W-1:0] kus_sparse_special_pf_addr;
  logic [ADDR_W-1:0] cmd_prefetch_train_addr;
  logic [ADDR_W:0] kus_sparse_special_gap_ext;
  logic [ADDR_W:0] kus_sparse_special_alt_step_ext;
  logic [ADDR_W:0] kus_sparse_special_pf_addr_ext;
