  logic [kcmu_pkg::KCMU_TOKEN_BLOCK_W-1:0] kus_kv_expiry_pending_token_block;
  kcmu_pkg::kcmu_kv_kind_t kus_kv_expiry_pending_expected_kind;
  logic [5:0] kus_kv_expiry_pending_bin;
  logic [2:0] kus_kv_expiry_pending_age;
