  // stat counters
  logic [31:0] stat_v140_pf_req_cnt;
  logic [31:0] stat_v140_pf_useful_cnt;
  logic [31:0] stat_v140_sliding_detect_cnt;
  logic [31:0] stat_v140_disabled_cnt;

  // v140 standalone always_ff
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      for (int i = 0; i < 4; i++) begin
        v140_token_fifo[i] <= 7'd0;
        v140_cache_tags[i]  <= 7'd0;
        v140_cache_addrs[i] <= {ADDR_W{1'b0}};
      end
      v140_cache_wr_ptr   <= 2'd0;
      v140_streak_cnt     <= 2'd0;
      v140_pf_pending     <= 1'b0;
      v140_pf_window_idx  <= 3'd0;
      v140_pf_req_cnt     <= 4'd0;
      v140_pf_useful_cnt  <= 4'd0;
      v140_disabled       <= 1'b0;
    end else begin
      // Token FIFO: shift on every read
      if (cmd_fire_read) begin
        v140_token_fifo[3] <= v140_token_fifo[2];
        v140_token_fifo[2] <= v140_token_fifo[1];
        v140_token_fifo[1] <= v140_token_fifo[0];
        v140_token_fifo[0] <= cmd_token_block_oracle[6:0];
      end

      // Cache: record (token, phys_addr) on successful mapper access
      if (cmd_fire_read && cmd_policy_select_s5_active) begin
        v140_cache_tags[v140_cache_wr_ptr]  <= cmd_token_block_oracle[6:0];
        v140_cache_addrs[v140_cache_wr_ptr] <= cmd_addr;
        v140_cache_wr_ptr <= v140_cache_wr_ptr + 2'd1;
      end

      // Streak: track consecutive nearby token_blocks
      if (cmd_fire_read) begin
        logic nearby_local;
        nearby_local = (v140_token_fifo[0][6:0] >= v140_token_fifo[1][6:0])
          ? (v140_token_fifo[0][6:0] - v140_token_fifo[1][6:0]) <= 7'd3
          : (v140_token_fifo[1][6:0] - v140_token_fifo[0][6:0]) <= 7'd3;
        if (nearby_local && v140_streak_cnt < 2'd3)
          v140_streak_cnt <= v140_streak_cnt + 2'd1;
        else if (!nearby_local && v140_streak_cnt > 2'd0)
          v140_streak_cnt <= v140_streak_cnt - 2'd1;
      end
    end
  end

  // Combinational: sliding detected
  assign v140_sliding_detected = (v140_streak_cnt >= 2'd2) && !v140_disabled;

  // v140 prefetch generation: on miss + sliding, lookup cache for token+1,+2,+3
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      v140_pf_pending    <= 1'b0;
      v140_pf_window_idx <= 3'd0;
      v140_pf_addr       <= {ADDR_W{1'b0}};
    end else begin
      // Trigger: sliding detected on read → queue small-window prefetch
      if (cmd_fire_read && v140_sliding_detected && !v140_pf_pending) begin
        v140_pf_pending    <= 1'b1;
        v140_pf_window_idx <= 3'd0;
        // Search cache for token_block+1
        if (v140_cache_tags[0] == (cmd_token_block_oracle[6:0] + 7'd1))
          v140_pf_addr <= v140_cache_addrs[0];
        else if (v140_cache_tags[1] == (cmd_token_block_oracle[6:0] + 7'd1))
          v140_pf_addr <= v140_cache_addrs[1];
        else if (v140_cache_tags[2] == (cmd_token_block_oracle[6:0] + 7'd1))
          v140_pf_addr <= v140_cache_addrs[2];
        else if (v140_cache_tags[3] == (cmd_token_block_oracle[6:0] + 7'd1))
          v140_pf_addr <= v140_cache_addrs[3];
        else
          v140_pf_pending <= 1'b0;
      end

      // Issue prefetch one per cycle
      if (v140_pf_pending && pf_ready && !hbm_if_congested && !hbm_if_write_pressure) begin
        v140_pf_window_idx <= v140_pf_window_idx + 3'd1;
        if (v140_pf_window_idx == 3'd1)  // 2 blocks (+1, +2)
          v140_pf_pending <= 1'b0;
        else if (v140_pf_window_idx == 3'd0) begin
          // Search cache for token_block+2
          if (v140_cache_tags[0] == (cmd_token_block_oracle[6:0] + 7'd2))
            v140_pf_addr <= v140_cache_addrs[0];
          else if (v140_cache_tags[1] == (cmd_token_block_oracle[6:0] + 7'd2))
            v140_pf_addr <= v140_cache_addrs[1];
          else if (v140_cache_tags[2] == (cmd_token_block_oracle[6:0] + 7'd2))
            v140_pf_addr <= v140_cache_addrs[2];
          else if (v140_cache_tags[3] == (cmd_token_block_oracle[6:0] + 7'd2))
            v140_pf_addr <= v140_cache_addrs[3];
          else
            v140_pf_pending <= 1'b0;
        end
      end

      // Auto-disable on pollution
      if (v140_pf_req_cnt >= 4'd15 && v140_pf_useful_cnt < {2'b0, v140_pf_req_cnt[3:2]})
        v140_disabled <= 1'b1;

      // Window reset
      if (v140_pf_req_cnt >= 4'd15) begin
        v140_pf_req_cnt    <= 4'd0;
        v140_pf_useful_cnt <= 4'd0;
      end
    end
  end

  // Stat counters
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      stat_v140_pf_req_cnt       <= 32'd0;
      stat_v140_pf_useful_cnt    <= 32'd0;
      stat_v140_sliding_detect_cnt <= 32'd0;
      stat_v140_disabled_cnt     <= 32'd0;
    end else begin
      if (v140_sliding_detected)
        stat_v140_sliding_detect_cnt <= stat_v140_sliding_detect_cnt + 32'd1;
      if (v140_pf_issue) begin
        stat_v140_pf_req_cnt <= stat_v140_pf_req_cnt + 32'd1;
        v140_pf_req_cnt <= v140_pf_req_cnt + 4'd1;
      end
      if (v140_disabled)
        stat_v140_disabled_cnt <= stat_v140_disabled_cnt + 32'd1;
    end
  end
`endif
