  assign cmd_h2o_structural_rescue_cap =
    (LINES >= 32) &&
    (L2_LINES >= 64) &&
    (L2_VB_LINES >= 32) &&
    (L2_GROUP_BUF_LINES >= 8);
  assign cmd_h2o_tiny_asym_q1_guard =
    (LINES <= 8) &&
    (L2_LINES <= 16) &&
    (L2_VB_LINES >= 16) &&
    (L2_GROUP_BUF_LINES <= 2) &&
    (cmd_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1));
  // v735/v736: dense/zero-descriptor streams in tiny-L1 + large-CVR cells do
  // not expose useful NSA structure, and the v722 high HH threshold removes
  // the backend/H2O protection that v251 uses to avoid extra HBM reads.  v735
  // tested a too-narrow all-zero descriptor restore.  v736 adds a cheap
  // far-reuse phase observer: q0, rd>=3 seeds a short TTL, then q0 reads in
  // that phase recover v251's zero HH threshold while uniform q0,rd1 streams
  // stay on v722's safer high threshold.
  assign cmd_h2o_zero_desc_farphase_seed =
    cmd_attn_h2o_en &&
    (LINES <= 8) &&
    (L2_LINES >= 64) &&
    (L2_VB_LINES >= 32) &&
    (cmd_query_structure_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) &&
    (cmd_reuse_distance_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3));
  assign cmd_h2o_zero_desc_tiny_l1_restore_guard =
    (LINES <= 8) &&
    (L2_LINES >= 64) &&
    (L2_VB_LINES >= 32) &&
    (cmd_query_structure_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) &&
`ifdef KCMU_CFG_FPGA_KILOSCORE_ZERO_DESC_FARPHASE_RESTORE_V736
    (cmd_temporal_persist_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
    ((cmd_reuse_distance_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
     (cmd_h2o_zero_desc_farphase_ttl != 6'd0));
`else
    (cmd_temporal_persist_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) &&
    (cmd_reuse_distance_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}});
`endif
  // v737: the c05 multimodal failure has a q1 local-window rail followed by
  // q3 special tokens.  v722 keeps q3 hot but suppresses the q1 rail in this
  // tiny-L1/large-CVR bucket, losing v251's backend/H2O protection.  Restore
  // q1 only for local-window descriptors; q0 dense remains controlled by the
  // v736 far-phase observer above.
  assign cmd_h2o_tiny_l1_q1_restore_guard =
`ifdef KCMU_CFG_FPGA_KILOSCORE_Q1_TINY_L1_RESTORE_V737
    (LINES <= 8) &&
    (L2_LINES >= 64) &&
    (L2_VB_LINES >= 32) &&
    (cmd_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
    (cmd_temporal_persist_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) &&
    (cmd_reuse_distance_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1));
`else
    1'b0;
`endif
  // v774: in equal L1/L2 capacity with tiny CVR/GB, a one-read mixed-phase
  // TTL is too short to protect the base/q0 tokens immediately after a
  // structured NSA/prefix island.  Extend only that existing observer; pure
  // uniform/dense/sliding streams never seed it.
  assign cmd_h2o_eqcap_mixphase_ttl_guard =
`ifdef KCMU_CFG_FPGA_KILOSCORE_EQCAP_MIXPHASE_TTL_V774
    (LINES == L2_LINES) &&
    (L2_VB_LINES <= 8) &&
    (L2_GROUP_BUF_LINES <= 2);
`else
    1'b0;
`endif
  assign cmd_h2o_mixphase_seed =
    cmd_attn_h2o_en &&
    (cmd_query_structure_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}});
  assign cmd_h2o_base_seen_seed =
    cmd_attn_h2o_en &&
    (cmd_query_structure_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}});
  assign cmd_h2o_mixphase_base_guard =
    cmd_attn_h2o_en &&
    (L2_LINES >= 32) &&
    (cmd_query_structure_class == {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) &&
    (cmd_temporal_persist_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
    (cmd_reuse_distance_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
    (cmd_h2o_mixphase_ttl != 6'd0);
  assign cmd_h2o_structural_only_guard =
    cmd_attn_h2o_en &&
    cmd_h2o_structural_rescue_cap &&
    (cmd_h2o_base_seen_ttl == 6'd0) &&
    ((cmd_query_structure_class == kcmu_pkg::KCMU_DESC_CLASS_W'(1)) ||
     (cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)));
  assign cmd_h2o_desc_sigrisk_soft_floor_base =
    cmd_attn_h2o_en &&
    (LINES <= 32) &&
    (L2_LINES <= 64) &&
    (((!cmd_policy_select_s5) &&
      ((cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) ||
       (cmd_temporal_persist_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) ||
       (cmd_reuse_distance_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) ||
       (cmd_oracle_service_criticality >= SCORE_W'(8'hB8)))) ||
     (cmd_policy_select_s5 &&
      (((cmd_spill_cost == kcmu_pkg::KCMU_COST_CLASS_W'(8)) &&
        cmd_sig_valid && ((cmd_query_sig ^ cmd_key_sig) >= 6'd8)) ||
       ((cmd_prefix_class == 2'd3) &&
        (cmd_query_structure_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
        (cmd_reuse_distance_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
        (cmd_router_class >= 2'd2))) &&
      ((cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) ||
       (cmd_temporal_persist_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) ||
       (cmd_reuse_distance_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) ||
       (cmd_oracle_service_criticality >= SCORE_W'(8'hB8)))));
  assign cmd_h2o_desc_qstruct_spill_floor_guard =
    cmd_attn_h2o_en &&
    (LINES <= 32) &&
    (L2_LINES <= 64) &&
    cmd_policy_select_s5 &&
    (cmd_prefix_class == 2'd3) &&
    (cmd_router_class >= 2'd3) &&
    (cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) &&
    (cmd_reuse_distance_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) &&
    (cmd_spill_cost >= kcmu_pkg::KCMU_COST_CLASS_W'(8));
  assign cmd_h2o_desc_qstruct_miss_floor_guard =
    cmd_h2o_desc_qstruct_spill_floor_guard &&
    cmd_h2o_l2_miss_heavy_phase;
  assign cmd_h2o_desc_qstruct_value_floor_guard =
    cmd_attn_h2o_en &&
    (LINES <= 32) &&
    (L2_LINES <= 64) &&
