  localparam integer KV_PT_PAGES = (ADDR_W <= KV_BLOCK_OFF_BITS) ? 1 : (1 << (ADDR_W - KV_BLOCK_OFF_BITS));
  logic [ADDR_W-1:0]   cmd_addr_phy;
  logic [ADDR_W-1:0]   cmd_addr_exec;
  logic [kcmu_pkg::KCMU_TOKEN_BLOCK_W-1:0] cmd_token_block_oracle;
  logic                kv_map_hit;
  logic                kv_map_alloc;
  logic                kv_map_overflow;

  function automatic logic [31:0] addr_to_32(input logic [ADDR_W-1:0] a);
    logic [31:0] ext;
    begin
      ext = 32'd0;
      ext[ADDR_W-1:0] = a;
      addr_to_32 = ext;
    end
  endfunction

  function automatic logic [kcmu_pkg::KCMU_TOKEN_BLOCK_W-1:0] token_block_from_meta(
    input logic [kcmu_pkg::KCMU_SEQ_W-1:0] seq_id,
    input logic [2:0] layer,
    input logic [1:0] head,
    input logic [11:0] token
  );
    logic [kcmu_pkg::KCMU_TOKEN_BLOCK_W-1:0] blk;
    begin
      blk = {kcmu_pkg::KCMU_TOKEN_BLOCK_W{1'b0}};
      blk[15:8] = seq_id;
      blk[7:5] = layer;
      blk[4:3] = head;
      blk[2:0] = token[5:3];
      token_block_from_meta = blk;
    end
  endfunction

  function automatic logic [2:0] popcount6(input logic [5:0] v);
    logic [2:0] count;
    begin
      count = 3'd0;
      count = count + {2'b00, v[0]};
      count = count + {2'b00, v[1]};
      count = count + {2'b00, v[2]};
      count = count + {2'b00, v[3]};
      count = count + {2'b00, v[4]};
      count = count + {2'b00, v[5]};
      popcount6 = count;
    end
  endfunction

  function automatic logic [2:0] cmd_qos_from_semantics(
    input logic              meta_valid,
    input logic [kcmu_pkg::KCMU_SEQ_W-1:0] seq_id,
    input kcmu_pkg::kcmu_phase_t phase,
    input kcmu_pkg::kcmu_kv_kind_t kv_kind,
    input logic [2:0]        layer,
    input logic [1:0]        head,
    input logic [11:0]       token,
    input logic [2:0]        prio,
    input logic [SCORE_W-1:0] score,
    input logic              is_read,
    input logic [ADDR_W-1:0] addr
  );
    logic signed [5:0] qos_tmp;
    begin
      if (!meta_valid) begin
        cmd_qos_from_semantics = kv_qos_from_addr(addr_to_32(addr), 1'b0, is_read);
      end else begin
        qos_tmp = $signed({1'b0, prio});
        if (is_read)        qos_tmp = qos_tmp + 6'sd1;
        if (phase == kcmu_pkg::KCMU_PHASE_DECODE) qos_tmp = qos_tmp + 6'sd2;
        if (kv_kind == kcmu_pkg::KCMU_KV_KIND_K)  qos_tmp = qos_tmp + 6'sd1;
        if (layer <= 3'd1)  qos_tmp = qos_tmp + 6'sd1;
        if (head == 2'd0)   qos_tmp = qos_tmp + 6'sd1;
        if (token[2:0] >= 3'd5) qos_tmp = qos_tmp + 6'sd1;
        if (seq_id[0])      qos_tmp = qos_tmp + 6'sd1;
        if (token[11])      qos_tmp = qos_tmp - 6'sd1;
        if ((phase == kcmu_pkg::KCMU_PHASE_PREFILL) && (qos_tmp > 0)) qos_tmp = qos_tmp - 6'sd1;
        if (score >= SCORE_W'(8'd192)) qos_tmp = qos_tmp + 6'sd1;
        else if ((score < SCORE_W'(8'd96)) && (qos_tmp > 0)) qos_tmp = qos_tmp - 6'sd1;

        if (qos_tmp < 0)       cmd_qos_from_semantics = 3'd0;
        else if (qos_tmp > 7)  cmd_qos_from_semantics = 3'd7;
        else                   cmd_qos_from_semantics = qos_tmp[2:0];
      end
    end
  endfunction

  always @(*) begin
    cmd_base_qos = cmd_qos_from_semantics(
      cmd_meta_valid,
      cmd_seq_id,
      cmd_phase,
      cmd_kv_kind,
      cmd_layer,
      cmd_head,
      cmd_token,
      cmd_prio,
      cmd_score,
      (cmd_op == KCMU_OP_RD),
      cmd_addr
    );
  end

  assign cmd_attn_h2o_en = H2O_V2_EN && cmd_attn_valid;
`ifdef KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
  assign cmd_policy_score_en = cmd_meta_valid && (cmd_op == KCMU_OP_RD);
`else
  assign cmd_policy_score_en = cmd_attn_h2o_en;
`endif
  assign cmd_policy_select_s5_active_raw = !UTILITY_POLICY_SELECT_EN || cmd_policy_select_s5;
`ifdef KCMU_CFG_FPGA_KILOSCORE_SPRINT_F_V1496_PROFILE_NEUTRAL
  assign cmd_policy_select_s5_active =
    trace_desc_kiloscore_extra_cvr_hint ? 1'b0 : cmd_policy_select_s5_active_raw;
`elsif KCMU_CFG_FPGA_KILOSCORE_SPRINT_F_V1496_PROFILE_NOGT
  assign cmd_policy_select_s5_active =
    trace_desc_kiloscore_extra_cvr_hint ? 1'b0 : cmd_policy_select_s5_active_raw;
`elsif KCMU_CFG_FPGA_KILOSCORE_SPRINT_G_V1496_SHORTZERO_NEUTRAL
  assign cmd_policy_select_s5_active =
    trace_desc_kiloscore_extra_cvr_hint ? 1'b0 : cmd_policy_select_s5_active_raw;
`elsif KCMU_CFG_FPGA_KILOSCORE_SPRINT_G_V1496_SHORTZERO_FULL
  assign cmd_policy_select_s5_active =
    trace_desc_kiloscore_extra_cvr_hint ? 1'b0 : cmd_policy_select_s5_active_raw;
`else
  assign cmd_policy_select_s5_active = cmd_policy_select_s5_active_raw;
`endif
`ifdef KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
  assign cmd_oracle_service_criticality = cmd_service_criticality;
`else
  assign cmd_oracle_service_criticality =
    (cmd_policy_select_s5_active || UTILITY_MARGINAL_REPL_EN) ?
      cmd_service_criticality : {SCORE_W{1'b0}};
`endif
  assign cmd_score_repl_active = UTILITY_SCORE_REPL_EN &&
                                 (!UTILITY_POLICY_SELECT_EN ||
                                  UTILITY_MARGINAL_REPL_EN ||
                                  cmd_policy_select_s5_active);
`ifdef KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
  assign cmd_utility_en = cmd_policy_score_en;
`else
  assign cmd_utility_en = cmd_attn_h2o_en &&
                          (UTILITY_HEAD_ADAPTIVE_EN ||
                           UTILITY_QUERY_AWARE_EN ||
                           UTILITY_COST_AWARE_EN ||
                           (UTILITY_BACKEND_CRITICAL_EN &&
                            (cmd_oracle_service_criticality != {SCORE_W{1'b0}})));
`endif
`ifdef KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
  // Native mode keeps the H2O oracle inactive, but still uses the existing
  // score-metadata datapath width for KiloScore class/utility propagation.
  localparam bit KCMU_POLICY_SCORE_PATH_EN = 1'b1;
`else
  localparam bit KCMU_POLICY_SCORE_PATH_EN = H2O_V2_EN;
`endif
  assign cmd_token_block_oracle = cmd_attn_valid ? cmd_token_block_id :
                                  token_block_from_meta(cmd_seq_id, cmd_layer, cmd_head, cmd_token);
  assign cmd_kus_token_forward =
    kus_prefetch_seen_read &&
    ((cmd_token_block_oracle[6:0] == (last_read_token_block_id[6:0] + 7'd1)) ||
     (cmd_token_block_oracle[6:0] == (last_read_token_block_id[6:0] + 7'd2)));
  assign cmd_kus_token_near =
    cmd_kus_token_forward ||
    (kus_prefetch_seen_read &&
     ((cmd_token_block_oracle[6:0] == last_read_token_block_id[6:0]) ||
      (last_read_token_block_id[6:0] == (cmd_token_block_oracle[6:0] + 7'd1)) ||
      (last_read_token_block_id[6:0] == (cmd_token_block_oracle[6:0] + 7'd2))));

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      kspu_epoch_read_cnt <= 8'd0;
      kspu_epoch_hot_cnt <= 8'd0;
      kspu_epoch_sliding_cnt <= 8'd0;
    end else if (!TRUE_H2O_KSPU_EPOCH_SELECTOR_EN) begin
      kspu_epoch_read_cnt <= 8'd0;
      kspu_epoch_hot_cnt <= 8'd0;
      kspu_epoch_sliding_cnt <= 8'd0;
    end else if (cmd_fire_read) begin
      if (kspu_epoch_read_cnt == 8'hff) begin
        kspu_epoch_read_cnt <= 8'd1;
        kspu_epoch_hot_cnt <=
          (cmd_hh_protect || (cmd_h2o_class != kcmu_pkg::KCMU_H2O_NEITHER)) ? 8'd1 : 8'd0;
        kspu_epoch_sliding_cnt <= cmd_kus_token_near ? 8'd1 : 8'd0;
      end else begin
        kspu_epoch_read_cnt <= kspu_epoch_read_cnt + 8'd1;
        if ((cmd_hh_protect || (cmd_h2o_class != kcmu_pkg::KCMU_H2O_NEITHER)) &&
            (kspu_epoch_hot_cnt != 8'hff)) begin
          kspu_epoch_hot_cnt <= kspu_epoch_hot_cnt + 8'd1;
        end
        if (cmd_kus_token_near && (kspu_epoch_sliding_cnt != 8'hff)) begin
          kspu_epoch_sliding_cnt <= kspu_epoch_sliding_cnt + 8'd1;
        end
      end
    end
  end

  assign cmd_kspu_epoch_selector_active =
    TRUE_H2O_KSPU_EPOCH_SELECTOR_EN &&
    (TRUE_H2O_KSPU_WORKLOAD_SELECTOR_EN ?
      cmd_policy_select_s5 :
      ((kspu_epoch_read_cnt >= 8'd145) &&
       (kspu_epoch_hot_cnt >= 8'd90) &&
       (kspu_epoch_hot_cnt <= 8'd124) &&
       (kspu_epoch_sliding_cnt >= 8'd96)));

  assign cmd_kspu_recent_valid_keep =
    cmd_kspu_epoch_selector_active &&
    cmd_attn_h2o_en &&
    (cmd_op == KCMU_OP_RD) &&
    cmd_recent_keep &&
    !cmd_compression_guard &&
    !hbm_if_congested &&
    ((cmd_hh_protect ||
      (cmd_h2o_class == kcmu_pkg::KCMU_H2O_BOTH) ||
      (cmd_query_relevance >= H2O_ADMISSION_QUERY_WARM_TH) ||
      (cmd_temporal_persist_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(1))));

  assign cmd_kspu_l2_reuse_promote_keep =
    TRUE_H2O_L2_REUSE_PROMOTE_EN &&
    cmd_attn_h2o_en &&
    (cmd_op == KCMU_OP_RD) &&
    true_h2o_l2_reuse_valid &&
    (true_h2o_l2_reuse_credit != 2'd0) &&
    (cmd_addr_exec == true_h2o_l2_reuse_addr) &&
    !hbm_if_write_pressure &&
    (cmd_hh_protect ||
     cmd_recent_keep_policy ||
     cmd_kus_token_near ||
     (cmd_query_relevance >= H2O_ADMISSION_QUERY_WARM_TH) ||
     (cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)));
  assign cmd_backend_critical_hot = UTILITY_BACKEND_CRITICAL_EN &&
                                    (cmd_service_criticality >=
                                      ((cmd_policy_select_s5_active || UTILITY_MARGINAL_REPL_EN) ?
                                        BACKEND_CRITICAL_HOT_TH :
                                        POLICY_SELECT_CONSERVATIVE_BACKEND_HOT_TH));
  assign cmd_backend_critical_warm = UTILITY_BACKEND_CRITICAL_EN &&
                                     (cmd_service_criticality >=
                                       ((cmd_policy_select_s5_active || UTILITY_MARGINAL_REPL_EN) ?
                                           BACKEND_CRITICAL_WARM_TH :
                                           POLICY_SELECT_CONSERVATIVE_BACKEND_WARM_TH));

  assign cmd_pressure_residual =
    UTILITY_MARGINAL_REPL_EN &&
    cmd_policy_select_s5_active &&
    cmd_utility_en &&
    (cmd_op == KCMU_OP_RD) &&
    (hbm_if_congested || hbm_if_write_pressure) &&
    ((cmd_service_criticality >= SCORE_W'(8'hA0)) ||
     ((cmd_query_relevance >= SCORE_W'(8'hA8)) &&
      (cmd_spill_cost >= kcmu_pkg::KCMU_COST_CLASS_W'(4))) ||
     ((cmd_query_relevance >= SCORE_W'(8'h98)) &&
      (cmd_compression_risk >= kcmu_pkg::KCMU_COST_CLASS_W'(7))));

  assign cmd_pollution_risk =
    UTILITY_MARGINAL_REPL_EN &&
    cmd_policy_select_s5_active &&
    cmd_utility_en &&
    !cmd_compression_guard &&
    (cmd_backend_priority_no_service <= 3'd1) &&
    (cmd_budget_class == kcmu_pkg::KCMU_HEAD_BUDGET_W'(0)) &&
    (cmd_utility_score < SCORE_W'(8'h90));

  assign cmd_marginal_keep =
    UTILITY_MARGINAL_REPL_EN &&
    cmd_policy_select_s5_active &&
    cmd_utility_en &&
    !cmd_pollution_risk &&
    !cmd_sched_victim_protect &&
    !cmd_hh_protect &&
    (cmd_h2o_class != kcmu_pkg::KCMU_H2O_BOTH) &&
    ((cmd_utility_score >= SCORE_W'(8'hD0)) ||
     (cmd_pressure_residual && (cmd_utility_score >= SCORE_W'(8'hA8))) ||
      ((cmd_spill_cost >= kcmu_pkg::KCMU_COST_CLASS_W'(5)) &&
       (cmd_query_relevance >= SCORE_W'(8'hA8)) &&
       (cmd_utility_score >= SCORE_W'(8'hB8))));

  // CAS-U separates "do not compress this line lossily" from "protect this line
  // as a victim/fill candidate". Workload results showed that broad compression
  // guard protection can pollute epoch/window reuse even when marginal_keep=0.
  assign cmd_compression_guard_can_protect =
    !UTILITY_MARGINAL_REPL_EN || cmd_marginal_keep || cmd_pressure_residual;

  // CAS-U backend actions must be actionable, not just high descriptor score.
  // This keeps HAQU/S4 behavior unchanged and prevents low-marginal lines from
  // winning fill/protect/backend order purely through broad service metadata.
  assign cmd_casu_backend_action_active =
    !UTILITY_MARGINAL_REPL_EN ||
    cmd_marginal_keep ||
    cmd_pressure_residual ||
    cmd_hh_protect ||
    (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_BOTH);

  assign cmd_h2o_admission_window =
    TRUE_H2O_BACKEND_ADMISSION_EN &&
    cmd_utility_en &&
    (cmd_op == KCMU_OP_RD) &&
    (hbm_if_congested ||
     hbm_if_write_pressure ||
     (hbm_if_q_level >= PF_HBM_Q_GUARD_TH));

  assign cmd_h2o_admission_hot =
    cmd_h2o_admission_window &&
    (cmd_query_relevance >= H2O_ADMISSION_QUERY_HOT_TH) &&
    (cmd_hh_protect || (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_BOTH));

  assign cmd_h2o_admission_warm =
    cmd_h2o_admission_window &&
    !cmd_h2o_admission_hot &&
    cmd_recent_keep_policy &&
    !cmd_compression_guard &&
    (cmd_query_relevance >= H2O_ADMISSION_QUERY_WARM_TH) &&
    (cmd_utility_score >= H2O_ADMISSION_UTILITY_WARM_TH);

  generate
    if (QMATCH_SIG_SERVICE_ADMISSION_EN) begin : g_qsig_service
      logic [5:0] cmd_qsig_query_fallback;
      logic [5:0] cmd_qsig_key_fallback;
      assign cmd_qsig_query_fallback =
        cmd_query_relevance[SCORE_W-1 -: 6] ^
        cmd_service_criticality[SCORE_W-1 -: 6] ^
        {cmd_layer[1:0], cmd_head, cmd_phase, cmd_kv_kind};
      assign cmd_qsig_key_fallback =
        cmd_attn_score[SCORE_W-1 -: 6] ^
        cmd_token_block_oracle[5:0] ^
        {cmd_token_block_oracle[8:6], cmd_budget_class, cmd_policy_select_s5_active};
      assign cmd_qsig_query =
        cmd_sig_valid ? cmd_query_sig : cmd_qsig_query_fallback;

      assign cmd_qsig_key =
        cmd_sig_valid ? cmd_key_sig : cmd_qsig_key_fallback;

      assign cmd_qsig_xor = cmd_qsig_query ^ cmd_qsig_key;
      assign cmd_qsig_dist = popcount6(cmd_qsig_xor);
      always @(*) begin
        unique case (cmd_qsig_dist)
          3'd0: cmd_qsig_score = SCORE_W'(8'hF0);
          3'd1: cmd_qsig_score = SCORE_W'(8'hD8);
          3'd2: cmd_qsig_score = SCORE_W'(8'hB8);
          3'd3: cmd_qsig_score = SCORE_W'(8'h90);
          default: cmd_qsig_score = SCORE_W'(8'h40);
        endcase
      end
      assign cmd_qsig_hot =
        (cmd_qsig_dist <= 3'd2) &&
        ((cmd_query_relevance >= SCORE_W'(8'h40)) ||
         (cmd_service_criticality >= SCORE_W'(8'h60)) ||
         (cmd_query_structure_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}));
      assign cmd_qsig_warm =
        (cmd_qsig_dist <= 3'd3) &&
        ((cmd_query_relevance >= SCORE_W'(8'h30)) ||
         (cmd_service_criticality >= SCORE_W'(8'h50)) ||
         (cmd_temporal_persist_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}));
    end else begin : g_qsig_service_off
      assign cmd_qsig_query = 6'd0;
      assign cmd_qsig_key = 6'd0;
      assign cmd_qsig_xor = 6'd0;
      assign cmd_qsig_dist = 3'd7;
      assign cmd_qsig_score = {SCORE_W{1'b0}};
      assign cmd_qsig_hot = 1'b0;
      assign cmd_qsig_warm = 1'b0;
    end
  endgenerate
  assign cmd_query_relevance_l2_base =
    (QMATCH_SIG_L2_PLACEMENT_EN && cmd_qsig_warm &&
     (cmd_qsig_score > cmd_query_relevance)) ? cmd_qsig_score : cmd_query_relevance;
  assign cmd_hasp_lrrb_l2_candidate =
    HASP_LRRB_L2_PLACEMENT_EN &&
    cmd_attn_h2o_en &&
    (cmd_op == KCMU_OP_RD) &&
    !cmd_compression_guard &&
    ((cmd_query_relevance >= HASP_LRRB_QUERY_TH) ||
     (cmd_budget_class >= kcmu_pkg::KCMU_HEAD_BUDGET_W'(HASP_LRRB_HEAD_BUDGET_TH)));
  assign cmd_query_relevance_l2_eff =
    (cmd_hasp_lrrb_l2_candidate &&
     (cmd_query_relevance_l2_base < HASP_LRRB_BOOST_SCORE)) ?
      HASP_LRRB_BOOST_SCORE : cmd_query_relevance_l2_base;

  assign cmd_qmatch_desc_query_ready =
    QMATCH_SERVICE_ADMISSION_EN &&
    TRUE_H2O_BACKEND_ADMISSION_EN &&
    cmd_utility_en &&
    (cmd_op == KCMU_OP_RD) &&
    !cmd_compression_guard &&
    (cmd_query_relevance >= SCORE_W'(8'h40)) &&
    (cmd_utility_score >= SCORE_W'(8'h40));

  assign cmd_qmatch_sig_query_ready =
    QMATCH_SIG_SERVICE_ADMISSION_EN &&
    TRUE_H2O_BACKEND_ADMISSION_EN &&
    cmd_utility_en &&
    (cmd_op == KCMU_OP_RD) &&
    !cmd_compression_guard &&
    cmd_qsig_warm &&
    (cmd_utility_score >= SCORE_W'(8'h40));

  assign cmd_qmatch_service_query_ready =
    cmd_qmatch_desc_query_ready || cmd_qmatch_sig_query_ready;

  assign cmd_qmatch_desc_admission_hot =
    cmd_qmatch_desc_query_ready &&
    (cmd_hh_protect ||
     (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_BOTH) ||
     (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_HEAVY_ONLY)) &&
    ((cmd_backend_priority_no_service >= 3'd2) ||
     (cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) ||
     (cmd_reuse_distance_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1)));

  assign cmd_qmatch_desc_admission_warm =
    cmd_qmatch_desc_query_ready &&
    !cmd_qmatch_desc_admission_hot &&
    cmd_recent_keep_policy &&
    (cmd_query_relevance >= SCORE_W'(8'h80)) &&
    (cmd_utility_score >= SCORE_W'(8'h60)) &&
    ((cmd_reuse_distance_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) ||
     (cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)));

  assign cmd_qmatch_sig_admission_hot =
    cmd_qmatch_sig_query_ready &&
    cmd_qsig_hot &&
    (cmd_hh_protect ||
     (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_BOTH) ||
     (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_HEAVY_ONLY)) &&
    ((cmd_backend_priority_no_service >= 3'd2) ||
     (cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) ||
     (cmd_reuse_distance_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) ||
     (cmd_service_criticality >= SCORE_W'(8'h70)));

  assign cmd_qmatch_sig_admission_warm =
    cmd_qmatch_sig_query_ready &&
    !cmd_qmatch_sig_admission_hot &&
    cmd_qsig_warm &&
    cmd_recent_keep_policy &&
    (cmd_utility_score >= SCORE_W'(8'h50)) &&
    !hbm_if_write_pressure &&
    ((cmd_reuse_distance_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) ||
     (cmd_temporal_persist_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) ||
     (cmd_service_criticality >= SCORE_W'(8'h80)));

  assign cmd_qmatch_service_admission_hot =
    cmd_qmatch_desc_admission_hot || cmd_qmatch_sig_admission_hot;

  assign cmd_qmatch_service_admission_warm =
    cmd_qmatch_desc_admission_warm || cmd_qmatch_sig_admission_warm;

  assign cmd_qsig_recent_cold_demote =
    QMATCH_SIG_RECENT_COLD_DEMOTE_EN &&
    cmd_qmatch_sig_query_ready &&
    !cmd_qsig_warm &&
    cmd_recent_keep &&
    !cmd_hh_protect &&
    (cmd_oracle_service_criticality < SCORE_W'(8'hC0)) &&
    (cmd_query_structure_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1));

  assign cmd_qsig_both_cold_to_hh =
    QMATCH_SIG_BOTH_COLD_TO_HH_EN &&
    cmd_qmatch_sig_query_ready &&
    !cmd_qsig_warm &&
    cmd_recent_keep &&
    cmd_hh_protect &&
    (cmd_oracle_service_criticality < SCORE_W'(8'hC0)) &&
    (cmd_query_structure_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1));

  assign cmd_qsig_both_nonhot_to_hh =
    QMATCH_SIG_BOTH_NONHOT_TO_HH_EN &&
    cmd_qmatch_sig_query_ready &&
    !cmd_qsig_hot &&
    cmd_recent_keep &&
    cmd_hh_protect &&
    (cmd_oracle_service_criticality < SCORE_W'(8'hC0)) &&
    (cmd_query_structure_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(1));

  kcmu_h2o_oracle #(
    .SCORE_W(SCORE_W),
    .RECENT_EN(TRUE_H2O_RECENT_EN),
    .HEAVY_HITTER_EN(TRUE_H2O_HH_EN),
    .HH_EPOCH_DECAY_EN(TRUE_H2O_HH_EPOCH_DECAY_EN),
    .HH_DECAY_LOG2(TRUE_H2O_HH_DECAY_LOG2),
    .HH_DECAY_MAX_SHIFT(TRUE_H2O_HH_DECAY_MAX_SHIFT),
    .HH_VALIDATED_PROTECT_EN(TRUE_H2O_HH_VALIDATED_PROTECT_EN),
    .HEAD_ADAPTIVE_EN(UTILITY_HEAD_ADAPTIVE_EN),
    .QUERY_AWARE_EN(UTILITY_QUERY_AWARE_EN),
    .COST_AWARE_EN(UTILITY_COST_AWARE_EN),
    .BACKEND_CRITICAL_EN(UTILITY_BACKEND_CRITICAL_EN),
    .UTILITY_ATTN_W(UTILITY_ATTN_W),
    .UTILITY_RECENT_W(UTILITY_RECENT_W),
    .UTILITY_HH_W(UTILITY_HH_W),
    .UTILITY_HEAD_W(UTILITY_HEAD_W),
    .UTILITY_QUERY_W(UTILITY_QUERY_W),
    .UTILITY_COMP_W(UTILITY_COMP_W),
    .UTILITY_SPILL_W(UTILITY_SPILL_W),
    .HH_SCORE_TH(TRUE_H2O_HH_SCORE_TH),
    .UTILITY_SERVICE_HH_EN(UTILITY_SERVICE_HH_EN),
    .UTILITY_SERVICE_HH_TH(UTILITY_SERVICE_HH_TH)
  ) u_h2o_oracle (
    .clk(clk),
    .rst_n(rst_n),
    .access_valid(H2O_V2_EN ? cmd_valid : 1'b0),
    .access_ready(cmd_ready),
    .access_is_demand(cmd_op == KCMU_OP_RD),
    .access_meta_valid(H2O_V2_EN ? cmd_meta_valid : 1'b0),
    .access_attn_valid(cmd_attn_h2o_en),
    .access_attn_score(cmd_h2o_oracle_attn_score),
    .access_hh_score_th(cmd_h2o_oracle_hh_score_th),
    .access_recent_rank(cmd_recent_rank),
    .access_token_block_id(cmd_token_block_oracle),
    .access_attn_epoch(cmd_attn_epoch),
    .access_head_budget_class(cmd_head_budget_class),
    .access_query_relevance(cmd_query_relevance),
    .access_compression_risk(cmd_compression_risk),
    .access_spill_cost(cmd_spill_cost),
    .access_service_criticality(cmd_oracle_service_criticality),
    .hh_hit(cmd_h2o_raw_hh_hit),
    .hh_protect(cmd_h2o_raw_hh_protect),
    .hh_score(cmd_h2o_raw_hh_score),
    .recent_keep(cmd_h2o_raw_recent_keep),
    .h2o_class(cmd_h2o_raw_class),
    .utility_score(cmd_h2o_raw_utility_score),
    .budget_class(cmd_h2o_raw_budget_class),
    .compression_guard(cmd_h2o_raw_compression_guard),
    .backend_priority_no_service(cmd_h2o_raw_backend_priority_no_service),
    .backend_priority(cmd_h2o_raw_backend_priority)
  );

  kcmu_kiloscore_native #(
    .ADDR_W(ADDR_W),
    .SCORE_W(SCORE_W),
    .LINES(LINES),
    .L2_LINES(L2_LINES),
    .L2_VB_LINES(L2_VB_LINES),
    .L2_GROUP_BUF_LINES(L2_GROUP_BUF_LINES)
  ) u_kiloscore_native (
    .clk(clk),
    .rst_n(rst_n),
    .access_valid(cmd_valid),
    .access_ready(cmd_ready),
    .access_is_read(cmd_op == KCMU_OP_RD),
    .access_is_write(cmd_op == KCMU_OP_WR),
    .access_meta_valid(cmd_meta_valid),
    .access_addr(cmd_addr_exec),
    .access_desc_score(cmd_score),
    .access_query_relevance(cmd_query_relevance),
    .access_service_criticality(cmd_oracle_service_criticality),
    .access_head_budget_class(cmd_head_budget_class),
    .access_temporal_persist_class(cmd_temporal_persist_class),
    .access_reuse_distance_class(cmd_reuse_distance_class),
    .access_query_structure_class(cmd_query_structure_class),
    .access_compression_risk(cmd_compression_risk),
    .access_spill_cost(cmd_spill_cost),
    .access_token_near(cmd_kus_token_near),
    .access_token_forward(cmd_kus_token_forward),
    .access_block_last(cmd_block_last),
    .backend_congested(hbm_if_congested),
    .backend_write_pressure(hbm_if_write_pressure),
    .native_hit(cmd_native_hh_hit),
    .native_protect(cmd_native_hh_protect),
    .native_l1_protect(cmd_native_l1_hh_protect),
    .native_score(cmd_native_hh_score),
    .native_recent_keep(cmd_native_recent_keep),
    .native_class(cmd_native_class),
    .native_utility_score(cmd_native_utility_score),
    .native_budget_class(cmd_native_budget_class),
    .native_compression_guard(cmd_native_compression_guard),
    .native_backend_priority_no_service(cmd_native_backend_priority_no_service),
    .native_backend_priority(cmd_native_backend_priority)
  );

`ifdef KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
