  assign cmd_compression_guard = cmd_native_compression_guard;
  assign cmd_backend_priority_no_service = cmd_native_backend_priority_no_service;
  assign cmd_backend_priority = cmd_native_backend_priority;
`else
  assign cmd_hh_hit = cmd_h2o_raw_hh_hit;
  assign cmd_hh_protect = cmd_h2o_raw_hh_protect;
  assign cmd_hh_score = cmd_h2o_raw_hh_score;
  assign cmd_recent_keep = cmd_h2o_raw_recent_keep;
  assign cmd_h2o_class = cmd_h2o_raw_class;
  assign cmd_utility_score = cmd_h2o_raw_utility_score;
