                           cmd_sched_hot_hint ||
                           cmd_sched_victim_protect ||
                           ((cmd_phase == kcmu_pkg::KCMU_PHASE_DECODE) && (cmd_head == 2'd0)) ||
                           ((cmd_layer <= 3'd1) && (cmd_head == 2'd0));
      cmd_sem_cold_legacy = (!kv_map_hit) &&
                     (cmd_score < SCORE_W'(8'd96)) &&
                     (cmd_layer >= 3'd4) &&
                     (cmd_head >= 2'd2) &&
                     (
                       ((cmd_phase == kcmu_pkg::KCMU_PHASE_PREFILL) &&
