                        (cmd_token[2:0] <= 3'd1))
                     );
    end else begin
      cmd_sem_hot_legacy = (cmd_base_qos >= 3'd5);
    end

    cmd_sem_hot = cmd_sem_hot_legacy;
    cmd_sem_cold = cmd_sem_cold_legacy;
