     ((cmd_sched_safe_query_admit_cnt >= SCHED_SAFE_EARLY_QUERY_TH) &&
      (cmd_sched_safe_query_admit_cnt <= SCHED_SAFE_EARLY_QUERY_HI_TH) &&
      (cmd_sched_safe_protect_cnt >= SCHED_SAFE_EARLY_PROTECT_TH) &&
      (cmd_sched_safe_backend_cnt <= SCHED_SAFE_EARLY_BACKEND_LOW_TH)));
  assign cmd_sched_safe_haqu_floor_active =
    ATTN_SCHED_SAFE_FALLBACK_EN &&
    (cmd_sched_safe_early_haqu_floor_active ||
