    (cmd_sched_safe_query_admit_cnt <= SCHED_SAFE_L2BIAS_QUERY_HI_TH) &&
    (cmd_sched_safe_protect_cnt >= SCHED_SAFE_L2BIAS_PROTECT_TH) &&
    (cmd_sched_safe_backend_cnt >= SCHED_SAFE_L2BIAS_BACKEND_LO_TH) &&
    (cmd_sched_safe_backend_cnt <= SCHED_SAFE_L2BIAS_BACKEND_HI_TH) &&
    (cmd_sched_safe_temporal_cnt >= SCHED_SAFE_L2BIAS_TEMPORAL_TH) &&
