    ATTN_SCHED_SAFE_FALLBACK_EN ||
    L2_SCHED_OWNERSHIP_QUERY_ADAPTIVE_BIAS_EN ||
    ATTN_SCHED_BACKEND_ISSUE_COUNTER_GATE_EN ||
    ATTN_SCHED_BACKEND_ISSUE_SELECTIVE_STRONG_GATE_EN;
  assign cmd_sched_backend_counter_gate_active =
    ATTN_SCHED_BACKEND_ISSUE_COUNTER_GATE_EN &&
    (((cmd_sched_safe_query_admit_cnt == 10'd0) &&
      (cmd_sched_safe_temporal_cnt >= SCHED_SAFE_EARLY_TEMPORAL_TH) &&
      (cmd_sched_safe_protect_cnt <= SCHED_SAFE_EARLY_PROTECT_LOW_TH) &&
      (cmd_sched_safe_backend_cnt <= SCHED_SAFE_EARLY_BACKEND_ZERO_TH) &&
      (cmd_sched_safe_h2o_hot_cnt <= SCHED_SAFE_BACKEND_GATE_H2O_ZERO_TH)) ||
     ((cmd_sched_safe_query_admit_cnt >= SCHED_SAFE_EARLY_QUERY_TH) &&
      (cmd_sched_safe_query_admit_cnt <= SCHED_SAFE_EARLY_QUERY_HI_TH) &&
      (cmd_sched_safe_protect_cnt >= SCHED_SAFE_EARLY_PROTECT_TH) &&
      (cmd_sched_safe_backend_cnt <= SCHED_SAFE_EARLY_BACKEND_LOW_TH) &&
      (cmd_sched_safe_h2o_hot_cnt <= SCHED_SAFE_BACKEND_GATE_H2O_LOW_TH)));
  assign cmd_sched_backend_selective_strong_gate_active =
    ATTN_SCHED_BACKEND_ISSUE_SELECTIVE_STRONG_GATE_EN &&
