  assign cmd_sched_phase_lowroi_window =
    ATTN_SCHED_PHASE_SELECTOR_EN &&
    (cmd_sched_phase_protect_cnt >= 10'd128) &&
    (cmd_sched_phase_temporal_cnt >= 10'd128) &&
    (cmd_sched_phase_backend_take_cnt >= 10'd128) &&
    (cmd_sched_phase_fill_effect_cnt <= 10'd4) &&
    (cmd_sched_phase_query_admit_cnt <= 10'd8) &&
    (cmd_sched_phase_h2o_hot_cnt <= 10'd4) &&
    (cmd_sched_phase_service_hi_cnt <= 10'd48);
`elsif KCMU_ABL_KUS_PROTECT_SELECTOR_V119
  assign cmd_sched_phase_lowroi_window =
    ATTN_SCHED_PHASE_SELECTOR_EN &&
    (cmd_sched_phase_protect_cnt >= 10'd128) &&
    (cmd_sched_phase_temporal_cnt >= 10'd128) &&
    (cmd_sched_phase_backend_take_cnt >= 10'd128) &&
    (cmd_sched_phase_fill_effect_cnt <= 10'd4) &&
    (cmd_sched_phase_query_admit_cnt <= 10'd8) &&
    (cmd_sched_phase_h2o_hot_cnt <= 10'd4) &&
    (cmd_sched_phase_service_hi_cnt <= 10'd48);
`else
  assign cmd_sched_phase_lowroi_window =
    ATTN_SCHED_PHASE_SELECTOR_EN &&
    (cmd_sched_phase_protect_cnt >= 10'd128) &&
    (cmd_sched_phase_temporal_cnt >= 10'd128) &&
    (cmd_sched_phase_backend_take_cnt >= 10'd8) &&
    (cmd_sched_phase_backend_take_cnt <= 10'd56) &&
    (cmd_sched_phase_fill_effect_cnt <= 10'd4) &&
    (cmd_sched_phase_query_admit_cnt <= 10'd48) &&
    (cmd_sched_phase_service_hi_cnt <= 10'd48);
`endif
`ifdef KCMU_ABL_KUS_RUNTIME_SELECTOR_V118
  assign cmd_sched_phase_mid_lowroi_window =
    ATTN_SCHED_PHASE_SELECTOR_EN &&
    !cmd_sched_phase_safe_mode &&
    (cmd_sched_phase_epoch_read_cnt >= 8'd191) &&
    (cmd_sched_phase_protect_cnt >= 10'd96) &&
    (cmd_sched_phase_temporal_cnt >= 10'd96) &&
    (cmd_sched_phase_backend_take_cnt >= 10'd96) &&
    (cmd_sched_phase_fill_effect_cnt <= 10'd4) &&
    (cmd_sched_phase_query_admit_cnt <= 10'd4) &&
    (cmd_sched_phase_h2o_hot_cnt <= 10'd4) &&
    (cmd_sched_phase_service_hi_cnt <= 10'd32);
`elsif KCMU_ABL_KUS_PROTECT_SELECTOR_V119
  assign cmd_sched_phase_mid_lowroi_window =
    ATTN_SCHED_PHASE_SELECTOR_EN &&
    !cmd_sched_phase_safe_mode &&
    (cmd_sched_phase_epoch_read_cnt >= 8'd191) &&
    (cmd_sched_phase_protect_cnt >= 10'd96) &&
    (cmd_sched_phase_temporal_cnt >= 10'd96) &&
    (cmd_sched_phase_backend_take_cnt >= 10'd96) &&
    (cmd_sched_phase_fill_effect_cnt <= 10'd4) &&
    (cmd_sched_phase_query_admit_cnt <= 10'd4) &&
    (cmd_sched_phase_h2o_hot_cnt <= 10'd4) &&
    (cmd_sched_phase_service_hi_cnt <= 10'd32);
`else
  assign cmd_sched_phase_mid_lowroi_window =
    ATTN_SCHED_PHASE_SELECTOR_EN &&
    !cmd_sched_phase_safe_mode &&
    (cmd_sched_phase_epoch_read_cnt >= 8'd191) &&
    (cmd_sched_phase_protect_cnt >= 10'd96) &&
    (cmd_sched_phase_temporal_cnt >= 10'd96) &&
    (cmd_sched_phase_backend_take_cnt >= 10'd8) &&
    (cmd_sched_phase_backend_take_cnt <= 10'd40) &&
    (cmd_sched_phase_fill_effect_cnt <= 10'd4) &&
    (cmd_sched_phase_query_admit_cnt <= 10'd32) &&
    (cmd_sched_phase_service_hi_cnt <= 10'd32);
`endif
  assign cmd_sched_capacity_lowroi_window =
    ATTN_SCHED_CAPACITY_PRESSURE_ADAPTIVE_EN &&
    (cmd_sched_phase_epoch_read_cnt >= 8'd191) &&
    (cmd_sched_phase_protect_cnt >= 10'd96) &&
    (cmd_sched_phase_temporal_cnt >= 10'd96) &&
    (cmd_sched_phase_backend_take_cnt >= 10'd6) &&
    (cmd_sched_phase_backend_take_cnt <= ((L2_LINES <= 16) ? 10'd24 : 10'd48)) &&
    (cmd_sched_phase_fill_effect_cnt <= 10'd4) &&
    (cmd_sched_phase_query_admit_cnt <= ((L2_LINES <= 16) ? 10'd8 : 10'd32)) &&
    (cmd_sched_phase_service_hi_cnt <= 10'd16);
  assign cmd_sched_phase_counter_en =
    ATTN_SCHED_PHASE_SELECTOR_EN ||
    ATTN_SCHED_CAPACITY_PRESSURE_ADAPTIVE_EN;
  assign cmd_sched_phase_dynamic_strong_gate =
    (ATTN_SCHED_PHASE_SELECTOR_EN && cmd_sched_phase_safe_mode) ||
    (ATTN_SCHED_CAPACITY_PRESSURE_ADAPTIVE_EN && cmd_sched_capacity_safe_mode);
  assign cmd_sched_safe_no_owner_active =
    ATTN_SCHED_SAFE_FALLBACK_EN &&
    !cmd_sched_safe_haqu_floor_active &&
    (cmd_sched_safe_query_admit_cnt >= SCHED_SAFE_QUERY_ADMIT_NOOWNER_TH) &&
    (cmd_sched_safe_protect_cnt >= SCHED_SAFE_PROTECT_NOOWNER_TH);
  assign cmd_sched_safe_owner_fallback_active =
    cmd_sched_safe_haqu_floor_active || cmd_sched_safe_no_owner_active;
  assign cmd_sched_safe_local_no_owner =
    ATTN_SCHED_SAFE_FALLBACK_LOCAL_EN &&
    cmd_utility_en &&
    (cmd_op == KCMU_OP_RD) &&
    cmd_sched_protect_take &&
    cmd_sched_temporal_take &&
    (ATTN_SCHED_SAFE_FALLBACK_LOCAL_AGGR_EN ||
     ((cmd_query_relevance >= H2O_ADMISSION_QUERY_WARM_TH) &&
      (cmd_utility_score >= SCORE_W'(8'h80))));

`ifdef KCMU_CFG_FPGA_KILOSCORE_DESC_TARGET_ROI_LATCH_V847
  assign cmd_sched_roi_guard_active =
    ATTN_SCHED_ROI_GUARD_EN &&
    (cmd_sched_roi_recent_bad_cnt != 3'd0) &&
    cmd_utility_en &&
    (cmd_op == KCMU_OP_RD) &&
    !cmd_sched_fill_take &&
    (cmd_sched_protect_take ||
     cmd_sched_victim_flip_take ||
     cmd_sched_backend_issue_take) &&
    !cmd_backend_critical_hot &&
    !cmd_h2o_admission_hot &&
    !cmd_pressure_residual;
`elsif KCMU_CFG_FPGA_KILOSCORE_DESC_TARGET_ROI_EAGER_V846
  assign cmd_sched_roi_guard_active =
    ATTN_SCHED_ROI_GUARD_EN &&
    (cmd_sched_roi_debt_cnt >= 4'd2) &&
    cmd_utility_en &&
    (cmd_op == KCMU_OP_RD) &&
    !cmd_sched_fill_take &&
    (cmd_sched_protect_take ||
     cmd_sched_victim_flip_take ||
     cmd_sched_backend_issue_take) &&
    !cmd_backend_critical_hot &&
    !cmd_h2o_admission_hot &&
    !cmd_pressure_residual;
`else
  assign cmd_sched_roi_guard_active =
    ATTN_SCHED_ROI_GUARD_EN &&
    (cmd_sched_roi_debt_cnt >= 4'd5) &&
    cmd_utility_en &&
    (cmd_op == KCMU_OP_RD) &&
    cmd_sched_protect_take &&
    !cmd_sched_fill_take &&
    !cmd_backend_critical_hot &&
    !cmd_h2o_admission_hot &&
    !cmd_pressure_residual;
`endif

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      cmd_sched_safe_query_admit_cnt <= 10'd0;
      cmd_sched_safe_protect_cnt <= 10'd0;
      cmd_sched_safe_backend_cnt <= 10'd0;
      cmd_sched_safe_temporal_cnt <= 10'd0;
      cmd_sched_safe_h2o_hot_cnt <= 10'd0;
    end else if (!cmd_sched_safe_counter_en) begin
      cmd_sched_safe_query_admit_cnt <= 10'd0;
      cmd_sched_safe_protect_cnt <= 10'd0;
      cmd_sched_safe_backend_cnt <= 10'd0;
      cmd_sched_safe_temporal_cnt <= 10'd0;
      cmd_sched_safe_h2o_hot_cnt <= 10'd0;
    end else begin
      if (l2_fill_query_admit_event && (cmd_sched_safe_query_admit_cnt != 10'h3ff)) begin
        cmd_sched_safe_query_admit_cnt <= cmd_sched_safe_query_admit_cnt + 10'd1;
      end
      if (cmd_fire_read && cmd_sched_protect_effect_final && (cmd_sched_safe_protect_cnt != 10'h3ff)) begin
        cmd_sched_safe_protect_cnt <= cmd_sched_safe_protect_cnt + 10'd1;
      end
      if (cmd_fire_read && cmd_sched_backend_issue_effect_final && (cmd_sched_safe_backend_cnt != 10'h3ff)) begin
        cmd_sched_safe_backend_cnt <= cmd_sched_safe_backend_cnt + 10'd1;
      end
      if (cmd_fire_read && cmd_sched_temporal_take && (cmd_sched_safe_temporal_cnt != 10'h3ff)) begin
        cmd_sched_safe_temporal_cnt <= cmd_sched_safe_temporal_cnt + 10'd1;
      end
      if (cmd_fire_read && cmd_h2o_admission_hot && (cmd_sched_safe_h2o_hot_cnt != 10'h3ff)) begin
        cmd_sched_safe_h2o_hot_cnt <= cmd_sched_safe_h2o_hot_cnt + 10'd1;
      end
    end
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      cmd_sched_phase_safe_mode <= 1'b0;
      cmd_sched_capacity_safe_mode <= 1'b0;
      cmd_sched_phase_epoch_read_cnt <= 8'd0;
      cmd_sched_phase_query_admit_cnt <= 10'd0;
      cmd_sched_phase_protect_cnt <= 10'd0;
      cmd_sched_phase_temporal_cnt <= 10'd0;
      cmd_sched_phase_backend_take_cnt <= 10'd0;
      cmd_sched_phase_backend_effect_cnt <= 10'd0;
      cmd_sched_phase_fill_effect_cnt <= 10'd0;
      cmd_sched_phase_service_hi_cnt <= 10'd0;
      cmd_sched_phase_h2o_hot_cnt <= 10'd0;
`ifndef SYNTHESIS
      stat_sched_phase_selector_epoch_cnt <= 32'd0;
      stat_sched_phase_selector_safe_epoch_cnt <= 32'd0;
      stat_sched_phase_selector_switch_cnt <= 32'd0;
      stat_sched_phase_selector_lowroi_cnt <= 32'd0;
      stat_sched_phase_selector_safe_read_cnt <= 32'd0;
      stat_kv_sibling_pending_set_cnt <= 32'd0;
      stat_kv_sibling_pending_match_cnt <= 32'd0;
      stat_kv_sibling_conf_hot_cnt <= 32'd0;
      stat_kv_sibling_keep_cnt <= 32'd0;
`endif
    end else if (!cmd_sched_phase_counter_en) begin
      cmd_sched_phase_safe_mode <= 1'b0;
      cmd_sched_capacity_safe_mode <= 1'b0;
      cmd_sched_phase_epoch_read_cnt <= 8'd0;
      cmd_sched_phase_query_admit_cnt <= 10'd0;
      cmd_sched_phase_protect_cnt <= 10'd0;
      cmd_sched_phase_temporal_cnt <= 10'd0;
      cmd_sched_phase_backend_take_cnt <= 10'd0;
      cmd_sched_phase_backend_effect_cnt <= 10'd0;
      cmd_sched_phase_fill_effect_cnt <= 10'd0;
      cmd_sched_phase_service_hi_cnt <= 10'd0;
      cmd_sched_phase_h2o_hot_cnt <= 10'd0;
    end else if (cmd_fire_read) begin
      if (cmd_sched_phase_epoch_read_cnt == 8'hff) begin
`ifndef SYNTHESIS
        stat_sched_phase_selector_epoch_cnt <= stat_sched_phase_selector_epoch_cnt + 32'd1;
        if (cmd_sched_phase_lowroi_window) begin
          stat_sched_phase_selector_lowroi_cnt <= stat_sched_phase_selector_lowroi_cnt + 32'd1;
          stat_sched_phase_selector_safe_epoch_cnt <= stat_sched_phase_selector_safe_epoch_cnt + 32'd1;
        end
        if (cmd_sched_phase_lowroi_window != cmd_sched_phase_safe_mode) begin
          stat_sched_phase_selector_switch_cnt <= stat_sched_phase_selector_switch_cnt + 32'd1;
        end
`endif
        cmd_sched_phase_safe_mode <= cmd_sched_phase_lowroi_window;
        cmd_sched_capacity_safe_mode <= cmd_sched_capacity_lowroi_window;
        cmd_sched_phase_epoch_read_cnt <= 8'd0;
        cmd_sched_phase_query_admit_cnt <= l2_fill_query_admit_event ? 10'd1 : 10'd0;
        cmd_sched_phase_protect_cnt <= cmd_sched_protect_effect_final ? 10'd1 : 10'd0;
        cmd_sched_phase_temporal_cnt <= cmd_sched_temporal_take ? 10'd1 : 10'd0;
        cmd_sched_phase_backend_take_cnt <= cmd_sched_backend_issue_take_final ? 10'd1 : 10'd0;
        cmd_sched_phase_backend_effect_cnt <= cmd_sched_backend_issue_effect_final ? 10'd1 : 10'd0;
        cmd_sched_phase_fill_effect_cnt <= cmd_sched_fill_effect_final ? 10'd1 : 10'd0;
        cmd_sched_phase_service_hi_cnt <=
          (cmd_service_criticality >= SCORE_W'(8'hB8)) ? 10'd1 : 10'd0;
        cmd_sched_phase_h2o_hot_cnt <= cmd_h2o_admission_hot ? 10'd1 : 10'd0;
      end else begin
        cmd_sched_phase_epoch_read_cnt <= cmd_sched_phase_epoch_read_cnt + 8'd1;
        if (cmd_sched_phase_mid_lowroi_window) begin
          cmd_sched_phase_safe_mode <= 1'b1;
`ifndef SYNTHESIS
          stat_sched_phase_selector_switch_cnt <= stat_sched_phase_selector_switch_cnt + 32'd1;
          stat_sched_phase_selector_lowroi_cnt <= stat_sched_phase_selector_lowroi_cnt + 32'd1;
`endif
        end
        if (cmd_sched_capacity_lowroi_window && !cmd_sched_capacity_safe_mode) begin
          cmd_sched_capacity_safe_mode <= 1'b1;
        end
        if (cmd_sched_phase_safe_mode) begin
`ifndef SYNTHESIS
          stat_sched_phase_selector_safe_read_cnt <= stat_sched_phase_selector_safe_read_cnt + 32'd1;
`endif
        end
        if (l2_fill_query_admit_event && (cmd_sched_phase_query_admit_cnt != 10'h3ff)) begin
          cmd_sched_phase_query_admit_cnt <= cmd_sched_phase_query_admit_cnt + 10'd1;
        end
        if (cmd_sched_protect_effect_final && (cmd_sched_phase_protect_cnt != 10'h3ff)) begin
          cmd_sched_phase_protect_cnt <= cmd_sched_phase_protect_cnt + 10'd1;
        end
        if (cmd_sched_temporal_take && (cmd_sched_phase_temporal_cnt != 10'h3ff)) begin
          cmd_sched_phase_temporal_cnt <= cmd_sched_phase_temporal_cnt + 10'd1;
        end
        if (cmd_sched_backend_issue_take_final && (cmd_sched_phase_backend_take_cnt != 10'h3ff)) begin
          cmd_sched_phase_backend_take_cnt <= cmd_sched_phase_backend_take_cnt + 10'd1;
        end
        if (cmd_sched_backend_issue_effect_final && (cmd_sched_phase_backend_effect_cnt != 10'h3ff)) begin
          cmd_sched_phase_backend_effect_cnt <= cmd_sched_phase_backend_effect_cnt + 10'd1;
        end
        if (cmd_sched_fill_effect_final && (cmd_sched_phase_fill_effect_cnt != 10'h3ff)) begin
          cmd_sched_phase_fill_effect_cnt <= cmd_sched_phase_fill_effect_cnt + 10'd1;
        end
        if ((cmd_service_criticality >= SCORE_W'(8'hB8)) &&
            (cmd_sched_phase_service_hi_cnt != 10'h3ff)) begin
          cmd_sched_phase_service_hi_cnt <= cmd_sched_phase_service_hi_cnt + 10'd1;
        end
        if (cmd_h2o_admission_hot && (cmd_sched_phase_h2o_hot_cnt != 10'h3ff)) begin
          cmd_sched_phase_h2o_hot_cnt <= cmd_sched_phase_h2o_hot_cnt + 10'd1;
        end
      end
    end
  end

  always @(*) begin
    if (ATTN_SCHED_EN) begin
      if (cmd_repl_hot_hint && (cmd_sched_qos < 3'd7)) begin
        cmd_qos = cmd_sched_qos + 3'd1;
      end else begin
        cmd_qos = cmd_sched_qos;
      end
      if (ATTN_SCHED_BACKEND_ISSUE_QOS_BOOST_EN &&
          cmd_sched_backend_issue_take &&
          (cmd_qos < 3'd7)) begin
        cmd_qos = cmd_qos + 3'd1;
      end
    end else begin
      cmd_qos = cmd_base_qos;
    end

    // Semantic-aware QoS shaping: protect hot tokens and suppress cold streams under congestion.
    if (cmd_sem_hot && (cmd_qos < 3'd7)) begin
      cmd_qos = cmd_qos + 3'd1;
    end
`ifdef KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_HASP_DESC_QOS_V272
    // v272: fold descriptor relevance into a tiny FPGA-friendly QoS ladder.
    // This is deliberately a placement/service hint, not a replacement scorer.
    if ((cmd_op == KCMU_OP_RD) && !cmd_compression_guard) begin
      if ((cmd_query_relevance >= SCORE_W'(8'hA8)) && (cmd_qos <= 3'd5)) begin
        cmd_qos = cmd_qos + 3'd2;
      end else if (((cmd_query_relevance >= SCORE_W'(8'h70)) ||
                    (cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
                    (cmd_budget_class >= kcmu_pkg::KCMU_HEAD_BUDGET_W'(1))) &&
                   (cmd_qos < 3'd7)) begin
        cmd_qos = cmd_qos + 3'd1;
      end
    end
`endif
`ifdef KCMU_ABL_KUS_KV_SIBLING_KEEP_V133
    if (cmd_kus_kv_sibling_keep && (cmd_qos < 3'd7)) begin
      cmd_qos = cmd_qos + 3'd1;
    end
`endif
    cmd_qos_pre_backend_critical = cmd_qos;
    if ((TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) &&
        cmd_utility_en && (cmd_backend_critical_hot || cmd_pressure_residual)) begin
      if (cmd_qos <= 3'd5) cmd_qos = cmd_qos + 3'd2;
      else cmd_qos = 3'd7;
    end else if ((TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) &&
                 cmd_utility_en && cmd_backend_critical_warm && (cmd_qos < 3'd7)) begin
      cmd_qos = cmd_qos + 3'd1;
    end
    cmd_qos_post_backend_critical = cmd_qos;
    if ((TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) && cmd_utility_en) begin
      if (cmd_backend_priority >= 3'd5) begin
        if (cmd_qos <= 3'd5) cmd_qos = cmd_qos + 3'd2;
        else cmd_qos = 3'd7;
      end else if (((cmd_backend_priority >= 3'd3) ||
                    (cmd_budget_class >= kcmu_pkg::KCMU_HEAD_BUDGET_W'(2))) &&
                   (cmd_qos < 3'd7)) begin
        cmd_qos = cmd_qos + 3'd1;
      end
    end else if ((TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) &&
                 cmd_attn_h2o_en && cmd_hh_protect) begin
      if (cmd_qos <= 3'd5) cmd_qos = cmd_qos + 3'd2;
      else cmd_qos = 3'd7;
    end else if ((TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) &&
                 cmd_attn_h2o_en && cmd_recent_keep_policy && (cmd_qos < 3'd7)) begin
      cmd_qos = cmd_qos + 3'd1;
    end
    cmd_qos_pre_h2o_admission = cmd_qos;
    if (cmd_h2o_admission_hot && (cmd_qos < 3'd7)) begin
      cmd_qos = cmd_qos + 3'd1;
    end else if (cmd_h2o_admission_warm && (cmd_qos < 3'd7)) begin
      cmd_qos = cmd_qos + 3'd1;
    end
    cmd_qos_post_h2o_admission = cmd_qos;
    if (hbm_if_congested && cmd_sem_cold && (cmd_qos > 3'd0)) begin
      cmd_qos = cmd_qos - 3'd1;
    end
    if (hbm_if_congested && cmd_sem_cold &&
        (hbm_if_q_level >= PF_HBM_Q_GUARD_TH) &&
        (cmd_base_qos <= 3'd2) &&
        (cmd_qos > 3'd0)) begin
      cmd_qos = cmd_qos - 3'd1;
    end

    cmd_slave_victim_protect = TRUE_H2O_BACKEND_ADMISSION_EN &&
                               ((cmd_utility_en &&
                                 ((cmd_compression_guard && cmd_compression_guard_can_protect) ||
                                  cmd_marginal_keep ||
                                  cmd_backend_critical_hot ||
                                   cmd_h2o_admission_hot ||
                                   cmd_qmatch_service_admission_hot ||
                                   (TRUE_H2O_SERVICE_HH_DIRECT_EN &&
                                    (cmd_hh_victim_protect_policy ||
                                     (cmd_h2o_class_victim_policy == kcmu_pkg::KCMU_H2O_BOTH))) ||
                                   (cmd_backend_priority >= 3'd4))) ||
                                 (!cmd_utility_en && cmd_attn_h2o_en &&
                                  (cmd_hh_victim_protect_policy ||
                                   (cmd_h2o_class_victim_policy == kcmu_pkg::KCMU_H2O_BOTH)))) ||
                               cmd_kspu_recent_valid_keep ||
                               cmd_kspu_l2_reuse_promote_keep;
    cmd_slave_fill_allow = (TRUE_H2O_BACKEND_ADMISSION_EN &&
                            ((cmd_utility_en &&
                              (cmd_marginal_keep ||
                               cmd_pressure_residual ||
                               cmd_backend_critical_warm ||
                               cmd_h2o_admission_hot ||
                               cmd_h2o_admission_warm ||
                               cmd_qmatch_service_admission_hot ||
                                cmd_qmatch_service_admission_warm ||
                                (TRUE_H2O_SERVICE_HH_DIRECT_EN &&
                                 (cmd_hh_retention_protect ||
                                  (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_BOTH))) ||
                                (cmd_backend_priority >= 3'd3) ||
                                (cmd_budget_class >= kcmu_pkg::KCMU_HEAD_BUDGET_W'(1)))) ||
                              (!cmd_utility_en && cmd_attn_h2o_en &&
                               (cmd_hh_retention_protect ||
                                (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_BOTH))))) ||
                           cmd_kspu_recent_valid_keep ||
                           cmd_kspu_l2_reuse_promote_keep ||
                           cmd_service_fill_rescue;
    if (TRUE_H2O_RETENTION_SERVICE_DECOUPLE_EN) begin
      cmd_slave_victim_protect =
        TRUE_H2O_BACKEND_ADMISSION_EN &&
        cmd_attn_h2o_en &&
        (cmd_hh_victim_protect_policy ||
         (cmd_h2o_class_victim_policy == kcmu_pkg::KCMU_H2O_BOTH));
      cmd_slave_fill_allow =
        (TRUE_H2O_BACKEND_ADMISSION_EN &&
         cmd_attn_h2o_en &&
         (cmd_hh_retention_protect ||
           (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_BOTH))) ||
        cmd_service_fill_rescue;
    end
`ifdef KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
    // Native KiloScore runs with the H2O backend-admission gate disabled.
    // Reintroduce L1 fill/protect ownership from native hardware-value
    // signals only; do not depend on the H2O oracle, HH table, or recent FIFO.
    if (cmd_fire_read) begin
      if (cmd_native_l1_hh_protect ||
          cmd_recent_keep_policy ||
          (cmd_h2o_class_policy != kcmu_pkg::KCMU_H2O_NEITHER) ||
          (cmd_utility_score >= SCORE_W'(8'h40)) ||
          (cmd_budget_class >= kcmu_pkg::KCMU_HEAD_BUDGET_W'(1))) begin
        cmd_slave_fill_allow = 1'b1;
      end
      if (cmd_native_hh_protect ||
          (cmd_utility_score >= SCORE_W'(8'h60)) ||
          (cmd_h2o_class_victim_policy == kcmu_pkg::KCMU_H2O_BOTH)) begin
        cmd_slave_victim_protect = 1'b1;
      end
    end
`endif
    if (cmd_sched_roi_guard_active) begin
      cmd_true_victim_protect = cmd_slave_victim_protect;
`ifdef KCMU_ABL_KUS_PROTECT_SELECTOR_V119
    end else if (cmd_sched_phase_safe_mode) begin
      cmd_true_victim_protect = cmd_slave_victim_protect;
`endif
    end else if (ATTN_SCHED_MASTER_SLAVE_PROTECT_EN &&
        !cmd_sched_safe_owner_fallback_active &&
        !cmd_sched_safe_local_no_owner) begin
      cmd_true_victim_protect = cmd_sched_protect_take ||
                                (cmd_slave_victim_protect && !cmd_sched_protect_req);
    end else begin
      cmd_true_victim_protect = cmd_sched_victim_protect || cmd_slave_victim_protect;
    end
`ifdef KCMU_ABL_KUS_GLOBAL_RETENTION_V141
    // v141: deep global tokens bypass scheduler and force victim_protect
    if (cmd_fire_read &&
        (cmd_layer <= 3'd3)) begin
      cmd_true_victim_protect = 1'b1;
    end
`endif
    if (ATTN_SCHED_MASTER_SLAVE_FILL_EN) begin
      // Only an actual scheduler take is allowed to override the slave fill
      // path. A fill request without a take should not collapse an otherwise
      // admissible slave fill into a read-bypass.
      cmd_true_fill_allow = cmd_sched_fill_take || cmd_slave_fill_allow;
    end else begin
      cmd_true_fill_allow = cmd_sched_fill_allow || cmd_slave_fill_allow;
    end
`ifdef KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_GF_PREFIX_PIN_V303
    // v303: descriptor-level prefix/special pinning.  This stays as a small
    // FPGA placement hint, not a new attention scorer: descriptors identify
    // prefix/special regions and hardware biases fill/protect for those reads.
    if (cmd_fire_read && (cmd_prefix_class != 2'd0)) begin
      cmd_true_victim_protect = 1'b1;
      cmd_true_fill_allow = 1'b1;
    end
`endif
`ifdef KCMU_ABL_KUS_KV_SIBLING_KEEP_V133
    if (cmd_kus_kv_sibling_keep) begin
      cmd_true_victim_protect = 1'b1;
      cmd_true_fill_allow = 1'b1;
    end
`endif
  end

  assign cmd_backend_critical_qos_boost =
    (TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) && cmd_utility_en &&
    (cmd_qos_post_backend_critical != cmd_qos_pre_backend_critical);

  assign cmd_exec_qos =
    TRUE_H2O_STORAGE_QOS_DECOUPLE_EN ? cmd_qos_pre_backend_critical : cmd_qos;

  assign cmd_h2o_admission_qos_boost =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    (cmd_qos_post_h2o_admission != cmd_qos_pre_h2o_admission);

  assign cmd_backend_critical_prio_raise =
    (TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) && cmd_utility_en &&
    (cmd_backend_priority != cmd_backend_priority_no_service);

  assign cmd_backend_critical_cross3 =
    (TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) && cmd_utility_en &&
    (cmd_backend_priority_no_service < 3'd3) &&
    (cmd_backend_priority >= 3'd3);

  assign cmd_backend_critical_cross4 =
    (TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) && cmd_utility_en &&
    (cmd_backend_priority_no_service < 3'd4) &&
    (cmd_backend_priority >= 3'd4);

  assign cmd_backend_critical_cross5 =
    (TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) && cmd_utility_en &&
    (cmd_backend_priority_no_service < 3'd5) &&
    (cmd_backend_priority >= 3'd5);

  assign cmd_backend_critical_fill_mask_sched =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    cmd_backend_critical_warm && cmd_sched_fill_allow;

  assign cmd_backend_critical_fill_mask_prio =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    cmd_backend_critical_warm && !cmd_sched_fill_allow &&
    (cmd_backend_priority_no_service >= 3'd3);

  assign cmd_backend_critical_fill_mask_budget =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    cmd_backend_critical_warm && !cmd_sched_fill_allow &&
    (cmd_backend_priority_no_service < 3'd3) &&
    (cmd_budget_class >= kcmu_pkg::KCMU_HEAD_BUDGET_W'(1));

  assign cmd_true_victim_protect_no_backend_critical =
    cmd_sched_victim_protect ||
    (TRUE_H2O_BACKEND_ADMISSION_EN &&
      ((cmd_utility_en &&
        (cmd_compression_guard ||
         (cmd_backend_priority_no_service >= 3'd4))) ||
       (!cmd_utility_en && cmd_attn_h2o_en &&
         (cmd_hh_retention_protect ||
          (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_BOTH)))));

  assign cmd_true_fill_allow_no_backend_critical =
    cmd_sched_fill_allow ||
    (TRUE_H2O_BACKEND_ADMISSION_EN &&
      ((cmd_utility_en &&
        ((cmd_backend_priority_no_service >= 3'd3) ||
         (cmd_budget_class >= kcmu_pkg::KCMU_HEAD_BUDGET_W'(1)))) ||
       (!cmd_utility_en && cmd_attn_h2o_en &&
         (cmd_hh_retention_protect ||
          (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_BOTH)))));

  assign cmd_true_victim_protect_no_h2o_admission =
    cmd_sched_victim_protect ||
    (TRUE_H2O_BACKEND_ADMISSION_EN &&
      ((cmd_utility_en &&
        ((cmd_compression_guard && cmd_compression_guard_can_protect) ||
         cmd_marginal_keep ||
         cmd_backend_critical_hot ||
         (cmd_backend_priority >= 3'd4))) ||
       (!cmd_utility_en && cmd_attn_h2o_en &&
         (cmd_hh_retention_protect ||
          (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_BOTH)))));

  assign cmd_true_fill_allow_no_h2o_admission =
    cmd_sched_fill_allow ||
    (TRUE_H2O_BACKEND_ADMISSION_EN &&
      ((cmd_utility_en &&
        (cmd_marginal_keep ||
         cmd_pressure_residual ||
         cmd_backend_critical_warm ||
         (cmd_backend_priority >= 3'd3) ||
         (cmd_budget_class >= kcmu_pkg::KCMU_HEAD_BUDGET_W'(1)))) ||
       (!cmd_utility_en && cmd_attn_h2o_en &&
         (cmd_hh_retention_protect ||
          (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_BOTH))))) ||
    cmd_service_fill_rescue;

  assign cmd_service_fill_rescue =
    TRUE_H2O_BACKEND_ADMISSION_EN &&
    UTILITY_SERVICE_RESCUE_EN &&
    cmd_utility_en &&
    (cmd_op == KCMU_OP_RD) &&
    hbm_if_congested &&
    !cmd_compression_guard &&
    !cmd_sched_fill_allow &&
    !cmd_true_fill_allow_no_backend_critical &&
    (cmd_backend_priority_no_service <= 3'd2) &&
    (cmd_service_criticality >= SERVICE_FILL_RESCUE_TH);

  assign cmd_service_issue_launch_gate =
    UTILITY_SERVICE_ISSUE_REQUIRE_FILLPROTECT ?
      (cmd_true_fill_allow || cmd_true_victim_protect) :
      1'b1;

  assign cmd_service_issue_guard_ok =
    UTILITY_SERVICE_ISSUE_ALLOW_GUARDED || !cmd_compression_guard;

  assign cmd_service_issue_prio_ok =
    UTILITY_SERVICE_ISSUE_RESIDUAL_EN ?
      ((cmd_backend_priority >= SERVICE_ISSUE_PRIO_TH) ||
       (cmd_backend_critical_warm &&
        (cmd_budget_class >= kcmu_pkg::KCMU_HEAD_BUDGET_W'(1))) ||
       (cmd_backend_critical_hot &&
         (cmd_backend_priority_no_service <= SERVICE_ISSUE_PRIO_TH)) ||
        cmd_pressure_residual) :
      (cmd_backend_priority >= SERVICE_ISSUE_PRIO_TH);

  assign cmd_service_issue_pressure_ok =
    hbm_if_write_pressure ||
    (TRUE_H2O_SERVICE_PACING_ONLY_EN && (cmd_backend_priority >= SERVICE_ISSUE_PRIO_TH)) ||
    (UTILITY_MARGINAL_REPL_EN && cmd_pressure_residual);

  assign cmd_backend_demand_bridge_prio_ok =
    (cmd_backend_priority >= 3'd4) || cmd_backend_critical_hot;

  assign cmd_backend_demand_bridge_window_ok =
    cmd_h2o_admission_window || cmd_pressure_residual;

  assign cmd_backend_demand_bridge_hh_ok =
    cmd_h2o_admission_hot ||
    cmd_hh_protect ||
    (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_BOTH);

  assign cmd_backend_demand_bridge_query_ok =
    cmd_h2o_admission_hot ||
    ((cmd_query_relevance >= H2O_ADMISSION_QUERY_HOT_TH) && cmd_recent_keep_policy);

  assign cmd_backend_demand_bridge_candidate =
    TRUE_H2O_BACKEND_ADMISSION_EN &&
    UTILITY_BACKEND_DEMAND_BRIDGE_EN &&
    cmd_policy_select_s5_active &&
    cmd_utility_en &&
    (cmd_op == KCMU_OP_RD) &&
    cmd_backend_demand_bridge_window_ok &&
    cmd_service_issue_launch_gate &&
    cmd_backend_demand_bridge_prio_ok &&
    (cmd_backend_demand_bridge_hh_ok || cmd_backend_demand_bridge_query_ok);

  assign cmd_backend_demand_bridge_boost =
    cmd_backend_demand_bridge_candidate &&
    cmd_service_issue_guard_ok;

  assign cmd_sched_backend_issue_take_final =
    (TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) &&
    UTILITY_SCHED_BACKEND_ISSUE_BRIDGE_EN &&
    (cmd_policy_select_s5_active || TRUE_H2O_SERVICE_PACING_ONLY_EN) &&
    cmd_utility_en &&
    (cmd_op == KCMU_OP_RD) &&
    (!ATTN_SCHED_BACKEND_ISSUE_STRONG_QUERY_GATE_EN ||
     !cmd_policy_select_s5 ||
     (cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
    (ATTN_SCHED_BACKEND_ISSUE_HIGH_SERVICE_ESCAPE_EN &&
      (cmd_service_criticality >= ATTN_SCHED_BACKEND_ISSUE_HIGH_SERVICE_TH))) &&
    (!ATTN_SCHED_BACKEND_ISSUE_COUNTER_GATE_EN ||
     !cmd_sched_backend_counter_gate_active ||
     !cmd_policy_select_s5 ||
     (cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
     (ATTN_SCHED_BACKEND_ISSUE_HIGH_SERVICE_ESCAPE_EN &&
      (cmd_service_criticality >= ATTN_SCHED_BACKEND_ISSUE_HIGH_SERVICE_TH))) &&
    (!ATTN_SCHED_BACKEND_ISSUE_SELECTIVE_STRONG_GATE_EN ||
     !cmd_sched_backend_selective_strong_gate_active ||
     (cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
     (ATTN_SCHED_BACKEND_ISSUE_HIGH_SERVICE_ESCAPE_EN &&
      (cmd_service_criticality >= ATTN_SCHED_BACKEND_ISSUE_HIGH_SERVICE_TH))) &&
    (!cmd_sched_phase_dynamic_strong_gate ||
     !cmd_policy_select_s5 ||
     (cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) ||
     (ATTN_SCHED_BACKEND_ISSUE_HIGH_SERVICE_ESCAPE_EN &&
      (cmd_service_criticality >= ATTN_SCHED_BACKEND_ISSUE_HIGH_SERVICE_TH))) &&
    cmd_sched_backend_issue_take &&
    !cmd_sched_roi_guard_active &&
    !cmd_sched_safe_haqu_floor_active &&
    !cmd_sched_safe_local_no_owner &&
    cmd_service_issue_pressure_ok &&
    cmd_service_issue_guard_ok &&
    cmd_service_issue_prio_ok &&
    cmd_service_issue_launch_gate &&
    (!UTILITY_SERVICE_ISSUE_REQUIRE_FILLPROTECT ||
     cmd_true_fill_allow ||
     cmd_true_victim_protect);

  assign cmd_sched_backend_issue_bridge_boost = cmd_sched_backend_issue_take_final;

  assign cmd_sched_service_issue_boost = cmd_sched_backend_issue_bridge_boost;
  assign cmd_slave_service_issue_boost =
    ((TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) &&
     UTILITY_SERVICE_ISSUE_EN &&
     (cmd_policy_select_s5_active || TRUE_H2O_SERVICE_PACING_ONLY_EN) &&
     cmd_utility_en &&
     (cmd_op == KCMU_OP_RD) &&
     cmd_service_issue_pressure_ok &&
     cmd_service_issue_guard_ok &&
     ((cmd_service_criticality >= SERVICE_ISSUE_BOOST_TH) || cmd_pressure_residual) &&
     cmd_service_issue_prio_ok &&
     cmd_service_issue_launch_gate) ||
    cmd_backend_demand_bridge_boost;
  assign cmd_service_issue_boost =
    cmd_sched_service_issue_boost ||
    (cmd_slave_service_issue_boost &&
     !(ATTN_SCHED_MASTER_SLAVE_BACKEND_EN && cmd_sched_backend_issue_take_final));
  assign cmd_sched_comp_guard_req =
    cmd_meta_valid &&
    cmd_utility_en &&
    cmd_compression_guard &&
    (cmd_op == KCMU_OP_RD);
  assign cmd_sched_comp_guard_take =
    cmd_sched_comp_guard_req &&
    !cmd_sched_safe_owner_fallback_active &&
    !cmd_sched_safe_local_no_owner &&
    ((ATTN_SCHED_MASTER_SLAVE_COMP_GUARD_EN && cmd_sched_protect_take) ||
     (cmd_sched_victim_protect && cmd_sched_protect_req));
  assign cmd_sched_fill_effect_final =
    cmd_sched_fill_take &&
    cmd_true_fill_allow;
  assign cmd_sched_protect_effect_final =
    cmd_sched_protect_take &&
    cmd_true_victim_protect;
  assign cmd_sched_victim_flip_effect_final =
    cmd_sched_victim_flip_take &&
    cmd_true_victim_protect;
  assign cmd_sched_backend_issue_effect_final =
    cmd_sched_backend_issue_take_final &&
    cmd_service_issue_boost &&
    !cmd_slave_service_issue_boost;

  assign cmd_sched_roi_positive_event =
    cmd_fire_read &&
    (cmd_sched_fill_effect_final ||
     cmd_sched_backend_issue_effect_final);

  assign cmd_sched_roi_negative_event =
    cmd_fire_read &&
    (cmd_sched_protect_effect_final ||
     cmd_sched_victim_flip_effect_final ||
     cmd_sched_backend_issue_take_final) &&
    !cmd_sched_fill_effect_final &&
    !cmd_sched_backend_issue_effect_final &&
    !cmd_backend_critical_fill_effective &&
    !cmd_h2o_admission_fill_effective;
  assign cmd_sched_slave_mask_fill_open =
    cmd_sched_fill_req &&
    !cmd_sched_fill_take &&
    !cmd_true_fill_allow &&
    cmd_slave_fill_allow &&
    !cmd_service_fill_rescue &&
    !cmd_backend_critical_warm;
  assign cmd_sched_slave_mask_fill_backend =
    cmd_sched_fill_req &&
    !cmd_sched_fill_take &&
    !cmd_true_fill_allow &&
    cmd_backend_critical_warm;
  assign cmd_sched_slave_mask_fill_service =
    cmd_sched_fill_req &&
    !cmd_sched_fill_take &&
    !cmd_true_fill_allow &&
    cmd_service_fill_rescue;
  assign cmd_sched_slave_mask_protect_hot =
    cmd_sched_protect_req &&
    !cmd_sched_protect_take &&
    cmd_slave_victim_protect &&
    !cmd_compression_guard;
  assign cmd_sched_slave_mask_protect_guard =
    cmd_sched_protect_req &&
    !cmd_sched_protect_take &&
    cmd_compression_guard &&
    cmd_compression_guard_can_protect;
  assign cmd_sched_slave_mask_backend_launch =
    cmd_sched_backend_issue_req &&
    !cmd_sched_service_issue_boost &&
    !cmd_service_issue_launch_gate;
  assign cmd_sched_slave_mask_backend_pressure =
    cmd_sched_backend_issue_req &&
    !cmd_sched_service_issue_boost &&
    !cmd_service_issue_pressure_ok;

  assign cmd_backend_critical_protect_effective =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    cmd_backend_critical_hot &&
    cmd_true_victim_protect &&
    !cmd_true_victim_protect_no_backend_critical;

  assign cmd_backend_critical_fill_effective =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    cmd_backend_critical_warm &&
    cmd_true_fill_allow &&
    !cmd_true_fill_allow_no_backend_critical;

  assign cmd_h2o_admission_protect_effective =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    cmd_h2o_admission_hot &&
    cmd_true_victim_protect &&
    !cmd_true_victim_protect_no_h2o_admission;

  assign cmd_h2o_admission_fill_effective =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    (cmd_h2o_admission_hot || cmd_h2o_admission_warm) &&
    cmd_true_fill_allow &&
    !cmd_true_fill_allow_no_h2o_admission;

  assign cmd_h2o_admission_fill_mask_sched =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    (cmd_h2o_admission_hot || cmd_h2o_admission_warm) &&
    cmd_sched_fill_allow;

  assign cmd_h2o_admission_fill_mask_prio =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    (cmd_h2o_admission_hot || cmd_h2o_admission_warm) &&
    !cmd_sched_fill_allow &&
    (cmd_backend_priority_no_service >= 3'd3);

  assign cmd_h2o_admission_fill_mask_budget =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    (cmd_h2o_admission_hot || cmd_h2o_admission_warm) &&
    !cmd_sched_fill_allow &&
    (cmd_backend_priority_no_service < 3'd3) &&
    (cmd_budget_class >= kcmu_pkg::KCMU_HEAD_BUDGET_W'(1));

  assign cmd_h2o_admission_protect_mask_sched =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    cmd_h2o_admission_hot &&
    cmd_sched_victim_protect;

  assign cmd_h2o_admission_protect_mask_guard =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    cmd_h2o_admission_hot &&
    !cmd_sched_victim_protect &&
    (cmd_compression_guard && cmd_compression_guard_can_protect);

  assign cmd_h2o_admission_protect_mask_prio =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    cmd_h2o_admission_hot &&
    !cmd_sched_victim_protect &&
    !(cmd_compression_guard && cmd_compression_guard_can_protect) &&
    !cmd_marginal_keep &&
    !cmd_backend_critical_hot &&
    (cmd_backend_priority >= 3'd4);

  assign cmd_backend_critical_protect_mask_sched =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    cmd_backend_critical_hot && cmd_sched_victim_protect;

  assign cmd_backend_critical_protect_mask_guard =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    cmd_backend_critical_hot && !cmd_sched_victim_protect &&
    cmd_compression_guard;

  assign cmd_backend_critical_protect_mask_prio =
    TRUE_H2O_BACKEND_ADMISSION_EN && cmd_utility_en &&
    cmd_backend_critical_hot && !cmd_sched_victim_protect &&
    !cmd_compression_guard &&
    (cmd_backend_priority_no_service >= 3'd4);

  always @(*) begin
    if (cmd_utility_en) begin
      if (cmd_compression_guard) begin
        cmd_compress_allow = 1'b0;
      end else begin
        cmd_compress_allow = !cmd_true_victim_protect &&
                             !kv_map_hit &&
                             (cmd_qos <= L2_COMPRESS_QOS_TH) &&
                             (cmd_compression_risk <= kcmu_pkg::KCMU_COST_CLASS_W'(6)) &&
                             (cmd_utility_score < SCORE_W'(8'hD8)) &&
                             !cmd_marginal_keep;
      end
    end else if (cmd_attn_h2o_en) begin
      unique case (cmd_h2o_class_policy)
        kcmu_pkg::KCMU_H2O_BOTH,
        kcmu_pkg::KCMU_H2O_HEAVY_ONLY: begin
          cmd_compress_allow = 1'b0;
        end
        kcmu_pkg::KCMU_H2O_RECENT_ONLY: begin
          cmd_compress_allow = !cmd_true_victim_protect &&
                               !kv_map_hit &&
                               (cmd_qos <= L2_COMPRESS_QOS_TH) &&
                               ((cmd_phase == kcmu_pkg::KCMU_PHASE_PREFILL) ||
                                ((cmd_phase == kcmu_pkg::KCMU_PHASE_DECODE) && (cmd_qos <= 3'd1)));
        end
        default: begin
          cmd_compress_allow = !cmd_true_victim_protect &&
                               !cmd_sem_hot &&
                               !kv_map_hit &&
                               (
                                 ((cmd_phase == kcmu_pkg::KCMU_PHASE_PREFILL) && (cmd_qos <= 3'd3)) ||
                                 ((cmd_phase == kcmu_pkg::KCMU_PHASE_DECODE) && (cmd_qos <= L2_COMPRESS_QOS_TH))
                               );
        end
      endcase
    end else begin
      cmd_compress_allow = !cmd_true_victim_protect &&
                           !cmd_sem_hot &&
                           (cmd_score < SCORE_W'(8'd96)) &&
                           !kv_map_hit &&
                           (cmd_layer >= 3'd4) &&
                           (cmd_head >= 2'd2) &&
                           (
                             ((cmd_phase == kcmu_pkg::KCMU_PHASE_PREFILL) &&
                              (cmd_token[2:0] <= 3'd3) &&
                              ((cmd_qos <= 3'd3) ||
                               (!cmd_meta_valid && (cmd_base_qos <= 3'd3)))) ||
                             ((cmd_phase == kcmu_pkg::KCMU_PHASE_DECODE) &&
                              (cmd_token[2:0] <= 3'd1) &&
                              (cmd_qos <= L2_COMPRESS_QOS_TH))
                           );
    end
    pf_fill_allow = pf_sem_hot || last_read_fill_allow;
    pf_victim_protect = pf_sem_hot || last_read_victim_protect;
`ifdef KCMU_ABL_KUS_L1_DEMAND_ONLY_V142
    // v142: L1 demand-only. All prefetches bypass L1, go direct to L2.
    // Prefetch never fills or protects L1 entries. Eliminates pollution.
    pf_fill_allow = 1'b0;
    pf_victim_protect = 1'b0;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_L2ONLY_SPARSE_PREFETCH_V207
    // v207: keep True-H2O service sparse prefetches as L2-only fills.
    // The goal is to recover miss-penalty benefit without L1 pollution.
    pf_fill_allow = 1'b0;
    pf_victim_protect = 1'b0;
`endif
    pf_compress_allow = !pf_sem_hot && last_read_compress_allow;
    pf_hh_protect = H2O_V2_EN && TRUE_H2O_BACKEND_ADMISSION_EN && (pf_sem_hot || last_read_hh_protect);
    pf_recent_keep = H2O_V2_EN && TRUE_H2O_BACKEND_ADMISSION_EN && last_read_recent_keep;
    pf_h2o_class = (H2O_V2_EN && TRUE_H2O_BACKEND_ADMISSION_EN) ? last_read_h2o_class : kcmu_pkg::KCMU_H2O_NEITHER;
    if (H2O_V2_EN &&
        (TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) &&
        (last_read_h2o_class != kcmu_pkg::KCMU_H2O_NEITHER) &&
`ifdef KCMU_ABL_KUS_PREFIX_STRIDE_V45
        !last_read_kus_adaptive_prefetch_phase &&
        !last_read_kus_special_prefetch_phase) begin
`else
        !last_read_kus_adaptive_prefetch_phase) begin
`endif
      pf_fill_allow = 1'b0;
      pf_victim_protect = 1'b0;
      pf_compress_allow = 1'b0;
      pf_hh_protect = 1'b0;
      pf_recent_keep = 1'b0;
      pf_h2o_class = kcmu_pkg::KCMU_H2O_NEITHER;
    end
`ifdef KCMU_ABL_KUS_TRI_PREFETCH_V37
    if (last_read_kus_adaptive_prefetch_phase &&
        !pf_sem_hot &&
        !last_read_hh_protect &&
        (last_read_h2o_class != kcmu_pkg::KCMU_H2O_HEAVY_ONLY) &&
        (last_read_h2o_class != kcmu_pkg::KCMU_H2O_BOTH)) begin
      pf_fill_allow = 1'b0;
      pf_victim_protect = 1'b0;
      pf_compress_allow = 1'b0;
      pf_hh_protect = 1'b0;
      pf_recent_keep = 1'b0;
