        (kus_prefix_special_streak_cnt >= (l1_healthy_v140 ? 3'd3 : 3'd2));
      if (cmd_kus_special_prefetch_sample) begin
        kus_prefix_special_streak_cnt <=
          (kus_prefix_special_streak_cnt == 3'd7) ? 3'd7 :
          (kus_prefix_special_streak_cnt + 3'd1);
      end else begin
        kus_prefix_special_streak_cnt <= 3'd0;
      end
`else
      last_read_kus_prefix_density_ok <=
        cmd_kus_special_prefetch_sample && (kus_prefix_special_streak_cnt >= 3'd2);
