`ifdef KCMU_ABL_KUS_KV_SIBLING_KEEP_V133
`ifdef KCMU_ABL_KUS_KV_LOGICAL_PAIR_DIRECT_V137
`ifdef KCMU_ABL_KUS_KV_LOGICAL_PAIR_GUARD_V138
  // v138 (CLOSED 2026-05-01): conf_hot-density guarded logical-pair keep.
  // Status: NEGATIVE/CONTROL EVIDENCE — marginal gain (+0.02~0.18% AMAT)
  // does not justify promotion over v44. See delivery/paper/
  // KILOWARE_KV_SIBLING_CLOSURE_V132_V138.md for full closure analysis.
  // Mechanism: only keep when conf_hot * 100 >= pending_set * 36.
  // Blocks Qwen CMQA low-confidence pollution while preserving most
  // Llama/gpt2-large sliding-window benefits.
  // 36% threshold: conf_hot / pending_set >= 0.36 => conf_hot * 100 >= pending_set * 36.
  // 100 = 64+32+4, 36 = 32+4. Shift+add: ~3 adders + 1 comparator.
  wire conf_hot_ok_v138 =
    ({1'b0, stat_kv_sibling_conf_hot_cnt[16:0], 6'b0} +      // conf_hot * 64
     {2'b0, stat_kv_sibling_conf_hot_cnt[16:0], 5'b0} +      // conf_hot * 32
     {5'b0, stat_kv_sibling_conf_hot_cnt[16:0], 2'b0}) >=    // conf_hot * 4
    ({2'b0, stat_kv_sibling_pending_set_cnt[16:0], 5'b0} +   // pending_set * 32
     {5'b0, stat_kv_sibling_pending_set_cnt[16:0], 2'b0});   // pending_set * 4
  assign cmd_kus_kv_sibling_keep =
    cmd_valid &&
    (cmd_op == KCMU_OP_RD) &&
    cmd_policy_select_s5_active &&
    kus_kv_expiry_pending_match &&
    conf_hot_ok_v138;
`else
  assign cmd_kus_kv_sibling_keep =
    cmd_valid &&
    (cmd_op == KCMU_OP_RD) &&
    cmd_policy_select_s5_active &&
    kus_kv_expiry_pending_match;
`endif
`else
  assign cmd_kus_kv_sibling_keep =
    cmd_valid &&
    (cmd_op == KCMU_OP_RD) &&
    cmd_policy_select_s5_active &&
    (kus_kv_expiry_pending_match || cmd_kus_kv_expiry_conf_hot) &&
    !hbm_if_congested &&
    !hbm_if_write_pressure &&
    ((cmd_temporal_persist_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) ||
     (cmd_reuse_distance_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) ||
     (cmd_query_structure_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) ||
     (cmd_query_relevance >= SCORE_W'(8'h80)));
`endif
`elsif KCMU_ABL_KUS_KV_SIBLING_META_KEEP_V134
  assign cmd_kus_kv_sibling_keep =
    cmd_valid &&
    (cmd_op == KCMU_OP_RD) &&
    cmd_policy_select_s5_active &&
    (kus_kv_expiry_pending_match || cmd_kus_kv_expiry_conf_hot) &&
    !hbm_if_congested &&
    !hbm_if_write_pressure &&
    ((cmd_temporal_persist_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) ||
     (cmd_reuse_distance_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) ||
     (cmd_query_structure_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) ||
     (cmd_query_relevance >= SCORE_W'(8'h80)));
`elsif KCMU_ABL_KUS_KV_SIBLING_META_SCORE_V135
  assign cmd_kus_kv_sibling_keep =
    cmd_valid &&
    (cmd_op == KCMU_OP_RD) &&
    cmd_policy_select_s5_active &&
    (kus_kv_expiry_pending_match || cmd_kus_kv_expiry_conf_hot) &&
    !hbm_if_congested &&
    !hbm_if_write_pressure &&
    ((cmd_temporal_persist_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) ||
     (cmd_reuse_distance_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) ||
     (cmd_query_structure_class != {kcmu_pkg::KCMU_DESC_CLASS_W{1'b0}}) ||
     (cmd_query_relevance >= SCORE_W'(8'h80)));
