`endif

`ifdef KCMU_ABL_KUS_SLIDING_WINDOW_PREFETCH_V139
  // v139 (CLOSED 2026-05-02): sliding-window temporal locality prefetch.
  // Status: NEGATIVE/CONTROL EVIDENCE. Detection logic works correctly
  // (streak counter, auto-disable), but prefetch target generation fails
  // because KV mapper scatters consecutive token_blocks across non-consecutive
  // physical addresses. Address-stride prefetch (+1, +2) has ~0% useful rate
  // under KV-cache address mapping. See delivery/paper/
  // KILOWARE_SLIDING_WINDOW_CLOSURE_V139.md.

  // Streak update: count consecutive nearby token_blocks
  wire v139_nearby =
    (cmd_token_block_oracle[6:0] >= v139_last_token_blocks[0][6:0])
      ? (cmd_token_block_oracle[6:0] - v139_last_token_blocks[0][6:0]) <= 7'd3
      : (v139_last_token_blocks[0][6:0] - cmd_token_block_oracle[6:0]) <= 7'd3;
  wire v139_streak_inc = v139_nearby && (v139_streak_cnt < 2'd3);
  wire v139_streak_dec = !v139_nearby && (v139_streak_cnt > 2'd0);

  assign v139_sliding_detected = (v139_streak_cnt >= 2'd3) && !v139_disabled;

  // Auto-disable: if useful < 25% after 32 prefetches, disable for rest of workload
  wire v139_pollution_exceed =
    (v139_pf_req_cnt >= 8'd32) &&
    (v139_pf_useful_cnt < {5'b0, v139_pf_req_cnt[7:2]});  // useful < req/4

  // v139_pf_issue: asserted when a v139 sliding-window prefetch is issued
  assign v139_pf_issue = v139_pf_pending && pf_ready && !hbm_if_congested && !hbm_if_write_pressure;

  // ----------------------------------------------------------
  // v139 sequential logic
  // ----------------------------------------------------------
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      for (int i = 0; i < 4; i++) v139_last_token_blocks[i] <= 7'd0;
      v139_streak_cnt    <= 2'd0;
      v139_pf_pending    <= 1'b0;
      v139_pf_window_idx <= 3'd0;
      v139_pf_addr_d[0]  <= 8'd0;
      v139_pf_addr_d[1]  <= 8'd0;
      v139_pf_addr_d[2]  <= 8'd0;
      v139_pf_req_cnt    <= 8'd0;
      v139_pf_useful_cnt <= 8'd0;
      v139_disabled      <= 1'b0;
    end else begin
      // Shift token_block history on each cmd_fire_read
      if (cmd_fire_read) begin
        v139_last_token_blocks[3] <= v139_last_token_blocks[2];
        v139_last_token_blocks[2] <= v139_last_token_blocks[1];
        v139_last_token_blocks[1] <= v139_last_token_blocks[0];
        v139_last_token_blocks[0] <= cmd_token_block_oracle[6:0];

        if (v139_streak_inc)
          v139_streak_cnt <= v139_streak_cnt + 2'd1;
        else if (v139_streak_dec)
          v139_streak_cnt <= v139_streak_cnt - 2'd1;
      end

      // On cmd_fire_read + sliding detected: queue small-window prefetch
      if (cmd_fire_read && v139_sliding_detected && !v139_pf_pending) begin
        v139_pf_pending    <= 1'b1;
        v139_pf_window_idx <= 3'd0;
        v139_pf_addr_d[0]  <= cmd_addr + 8'd1;
        v139_pf_addr_d[1]  <= cmd_addr + 8'd2;
      end

      // Issue prefetches one per cycle while pending
      if (v139_pf_pending && pf_ready && !hbm_if_congested && !hbm_if_write_pressure) begin
        v139_pf_window_idx <= v139_pf_window_idx + 3'd1;
        if (v139_pf_window_idx == 3'd1)  // 2 blocks total (+1, +2)
          v139_pf_pending <= 1'b0;
      end

      // Auto-disable on pollution
      if (v139_pollution_exceed)
        v139_disabled <= 1'b1;

      // Windowed counters: reset every 128 sliding prefetches
      if (v139_pf_req_cnt >= 8'd128) begin
        v139_pf_req_cnt    <= 8'd0;
        v139_pf_useful_cnt <= 8'd0;
      end

      // v139 stat counters (32-bit for final reporting)
      if (v139_sliding_detected)
        stat_v139_streak_detect_cnt <= stat_v139_streak_detect_cnt + 32'd1;
      if (v139_pf_issue) begin
        stat_v139_pf_req_cnt <= stat_v139_pf_req_cnt + 32'd1;
        v139_pf_req_cnt <= v139_pf_req_cnt + 8'd1;  // 8-bit window counter
      end
      if (v139_disabled)
        stat_v139_disabled_cnt <= stat_v139_disabled_cnt + 32'd1;
    end
  end
`endif

