                                last_read_kus_special_prefetch_phase ||
                                last_read_kus_sliding_prefetch_phase) &&
                               ((!ATTN_SCHED_EN) || cmd_sched_pf_allow ||
                                last_read_kus_special_prefetch_phase ||
                                last_read_kus_sliding_prefetch_phase) &&
                               ((!hbm_if_congested) || (last_read_qos >= PF_QOS_TH) ||
                                last_read_sem_hot || last_read_kus_special_prefetch_phase) &&
                               ((cmdq_level < CMDQ_W'(CMDQ_PREF_BLOCK_TH)) ||
                                last_read_sem_hot || last_read_kus_special_prefetch_phase) &&
                               ((hbm_if_q_level < PF_HBM_Q_GUARD_TH) ||
                                last_read_sem_hot || (last_read_qos >= PF_HOT_QOS_GUARD_TH) ||
                                last_read_kus_special_prefetch_phase);
`elsif KCMU_ABL_KUS_PREFIX_SLIDE_CREDIT_V43
  assign prefetch_enable_dyn = prefetch_enable &&
                               (!H2O_V2_EN || !TRUE_H2O_BACKEND_ADMISSION_EN ||
                                (last_read_h2o_class == kcmu_pkg::KCMU_H2O_NEITHER) ||
                                last_read_kus_special_prefetch_phase ||
                                last_read_kus_sliding_prefetch_phase) &&
                               ((!ATTN_SCHED_EN) || cmd_sched_pf_allow ||
                                last_read_kus_special_prefetch_phase ||
                                last_read_kus_sliding_prefetch_phase) &&
                               ((!hbm_if_congested) || (last_read_qos >= PF_QOS_TH) ||
                                last_read_sem_hot || last_read_kus_special_prefetch_phase ||
                                last_read_kus_sliding_prefetch_phase) &&
                               ((cmdq_level < CMDQ_W'(CMDQ_PREF_BLOCK_TH)) ||
                                last_read_sem_hot || last_read_kus_special_prefetch_phase ||
                                last_read_kus_sliding_prefetch_phase) &&
                               ((hbm_if_q_level < PF_HBM_Q_GUARD_TH) ||
                                last_read_sem_hot || (last_read_qos >= PF_HOT_QOS_GUARD_TH) ||
                                last_read_kus_special_prefetch_phase ||
                                last_read_kus_sliding_prefetch_phase);
`elsif KCMU_CFG_FPGA_KILOSCORE_NATIVE_STANDALONE
  // Native scoring must not inherit the legacy H2O-off prefetch escape hatch.
  // Until a native prefetch-value gate is proven, keep prefetch disabled so the
  // standalone scorer is evaluated through demand/CVR/Group-Fill decisions.
  assign prefetch_enable_dyn = 1'b0;
`else
  assign prefetch_enable_dyn = prefetch_enable &&
                               (!H2O_V2_EN ||
                                !(TRUE_H2O_BACKEND_ADMISSION_EN || TRUE_H2O_SERVICE_PACING_ONLY_EN) ||
                                (last_read_h2o_class == kcmu_pkg::KCMU_H2O_NEITHER) ||
                                (TRUE_H2O_SPACED_PREFETCH_EN &&
                                  (TRUE_H2O_SPACED_PREFETCH_DIV8_EN ?
                                    (last_read_token_block_id[2:0] == 3'b000) :
                                    (last_read_token_block_id[1:0] == 2'b00)) &&
                                  (!TRUE_H2O_HH_PREFETCH_ONLY_EN ||
                                   (last_read_h2o_class == kcmu_pkg::KCMU_H2O_HEAVY_ONLY) ||
                                   (last_read_h2o_class == kcmu_pkg::KCMU_H2O_BOTH)) &&
                                  (!TRUE_H2O_IDLE_PREFETCH_EN ||
                                   ((!hbm_if_congested) && (hbm_if_q_level == '0))) &&
                                  (!TRUE_H2O_OCCUPANCY_PREFETCH_EN ||
                                   ((!hbm_if_congested) &&
                                    (hbm_if_q_level <= HBM_Q_W'(TRUE_H2O_PREFETCH_QMAX)))) &&
                                  (!TRUE_H2O_PREFETCH_WRITE_PRESSURE_GUARD_EN ||
                                   (!hbm_if_write_pressure)) &&
                                  (!TRUE_H2O_PREFETCH_DESC_GATE_EN ||
                                   (last_read_query_relevance >= SCORE_W'(8'h68)) ||
                                   (last_read_service_criticality >= SCORE_W'(8'h70))) &&
                                  (!TRUE_H2O_PREFETCH_UTILITY_DESC_GATE_EN ||
                                   (((last_read_query_relevance >= SCORE_W'(8'h68)) ||
                                     (last_read_service_criticality >= SCORE_W'(8'h70))) &&
                                    (last_read_temporal_persist_class != '0) &&
                                    (last_read_sched_urgency_hint != '0) &&
                                    (last_read_reuse_distance_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(2)))) &&
                                  (!TRUE_H2O_UNCONGESTED_PREFETCH_EN ||
                                   (!hbm_if_congested)) &&
                                  (!TRUE_H2O_PREFETCH_NO_SPECIAL_EN ||
                                   !((last_read_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(3)) &&
                                     (last_read_reuse_distance_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) &&
                                     (last_read_temporal_persist_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)))) &&
                                  true_h2o_pf_wrdom_hhonly_gate_ok &&
                                  true_h2o_pf_budget_ok &&
                                  true_h2o_pf_useful_credit_ok &&
                                  true_h2o_pf_miss_credit_ok) ||
                                 last_read_kus_adaptive_prefetch_phase) &&
                               ((!ATTN_SCHED_EN) || cmd_sched_pf_allow ||
                                last_read_kus_adaptive_prefetch_phase) &&
                               ((!hbm_if_congested) || (last_read_qos >= PF_QOS_TH) || last_read_sem_hot) &&
                               ((cmdq_level < CMDQ_W'(CMDQ_PREF_BLOCK_TH)) || last_read_sem_hot) &&
                               ((hbm_if_q_level < PF_HBM_Q_GUARD_TH) || last_read_sem_hot ||
                                (last_read_qos >= PF_HOT_QOS_GUARD_TH));
`endif

  kcmu_kv_mapper #(
    .ADDR_W(ADDR_W),
    .TOKEN_W(12),
    .BLOCK_OFF_BITS(KV_BLOCK_OFF_BITS),
    .DIR_ENTRIES(KV_DIR_ENTRIES),
    .PT_PAGES(KV_PT_PAGES),
    .REAL_KV_LAYOUT_EN(KV_REAL_LAYOUT_EN),
    .TOKEN_BLOCK_BITS(KV_TOKEN_BLOCK_BITS),
    .KV_TYPE_ADDR_BIT(KV_TYPE_ADDR_BIT),
    .SCORE_REPL_EN(KV_MAP_SCORE_REPL_EN),
    .SCORE_REPL_HW_WIN(KV_MAP_SCORE_REPL_HW_WIN),
    .SCORE_PROTECT_TH(KV_MAP_SCORE_PROTECT_TH),
    .SCORE_DECAY_EN(KV_MAP_SCORE_DECAY_EN),
    .SCORE_DECAY_LOG2(KV_MAP_SCORE_DECAY_LOG2)
  ) u_kv_map (
    .clk(clk),
    .rst_n(rst_n),
    .access_valid(cmd_valid),
    .access_ready(cmd_ready),
    .access_op(cmd_op),
    .meta_valid(cmd_meta_valid),
    .seq_id(cmd_seq_id),
    .phase(cmd_phase),
    .kv_kind(cmd_kv_kind),
    .layer(cmd_layer),
    .head(cmd_head),
    .token(cmd_token),
    .logical_addr(cmd_addr),
    .attn_hint_qos(cmd_qos),
    .access_victim_protect(cmd_true_victim_protect),
    .access_compress_allow(cmd_compress_allow),
    .physical_addr(cmd_addr_phy),
    .map_hit(kv_map_hit),
    .map_alloc(kv_map_alloc),
    .map_overflow(kv_map_overflow),
    .stat_map_overflow_cnt_o(stat_map_overflow_cnt),
    .stat_map_repl_cnt_o(stat_map_repl_cnt),
    .stat_map_seq_reclaim_cnt_o(stat_map_seq_reclaim_cnt)
  );

  assign cmd_addr_exec = KV_MAP_ENABLE ? cmd_addr_phy : cmd_addr;
  logic              pf_valid;
  logic              pf_ready;
  logic [ADDR_W-1:0] pf_addr;
  logic              pf_valid_main;
  logic              pf_ready_main;
  logic [ADDR_W-1:0] pf_addr_main;
  logic              pf_demand_preempt_block;
  logic              pf_demand_preempt_drop;
  logic              ex_pf_fill_pulse;
  logic              ex_pf_useful_pulse;
  logic              pf_enable_d;
  logic              pf_access_fire_d;
  logic [ADDR_W-1:0] pf_access_addr_d;
  logic [2:0]        pf_access_qos_d;
  logic              pf_access_miss_penalty_phase_d;
  logic [31:0]       stat_demand_miss_cnt_q;
  logic              ex_demand_miss_pulse;

  assign ex_demand_miss_pulse = (stat_demand_miss_cnt != stat_demand_miss_cnt_q);

  always @(posedge clk) begin
    if (!rst_n) begin
      pf_enable_d      <= 1'b0;
      pf_access_fire_d <= 1'b0;
      pf_access_addr_d <= {ADDR_W{1'b0}};
      pf_access_qos_d  <= 3'd0;
      pf_access_miss_penalty_phase_d <= 1'b0;
      stat_demand_miss_cnt_q <= 32'd0;
    end else begin
      stat_demand_miss_cnt_q <= stat_demand_miss_cnt;
      pf_enable_d      <= prefetch_enable_dyn && !PREFETCH_FORCE_DISABLE_EN;
`ifdef KCMU_ABL_KUS_PREFIX_STRIDE_V45
      pf_access_fire_d <= cmd_fire_read &&
                           ((!cmd_kus_special_stream_mode) ||
                            cmd_kus_special_prefetch_sample);
`else
      pf_access_fire_d <= cmd_fire_read;
`endif
      pf_access_miss_penalty_phase_d <= 1'b0;
      if (cmd_fire_read) begin
`ifdef SYNTHESIS
        // Keep synthesis timing bounded: avoid mapper->prefetch direct combinational dependency.
        pf_access_addr_d <= cmd_addr;
`else
        pf_access_addr_d <= cmd_addr_exec;
`endif
`ifdef KCMU_ABL_KUS_PREFIX_SPECIAL_V39
        pf_access_qos_d  <= cmd_kus_adaptive_prefetch_sample ? 3'd7 : cmd_qos;
`elsif KCMU_ABL_KUS_PHASE_DENSITY_V49
        pf_access_qos_d  <= cmd_kus_adaptive_prefetch_sample ? 3'd7 : cmd_qos;
`elsif KCMU_ABL_KUS_MISS_PENALTY_PREFETCH_V47
        pf_access_qos_d  <= (cmd_kus_special_prefetch_sample && (kus_prefix_special_streak_cnt >= 3'd2)) ? 3'd7 :
                            (cmd_kus_miss_penalty_prefetch_sample && (cmd_qos < 3'd4)) ? 3'd4 :
                            cmd_qos;
        pf_access_miss_penalty_phase_d <= cmd_kus_miss_penalty_prefetch_sample;
`elsif KCMU_ABL_KUS_PREFIX_DENSITY_V44
        pf_access_qos_d  <= cmd_kus_adaptive_prefetch_sample ? 3'd7 : cmd_qos;
`elsif KCMU_ABL_KUS_PREFIX_ALT_STRIDE_V46
        pf_access_qos_d  <= cmd_kus_adaptive_prefetch_sample ? 3'd7 : cmd_qos;
`elsif KCMU_ABL_KUS_PREFIX_STRIDE_V45
        pf_access_qos_d  <= cmd_kus_adaptive_prefetch_sample ? 3'd7 :
                            (cmd_kus_special_prefetch_sample && (cmd_qos < 3'd6)) ? 3'd6 :
                            cmd_qos;
`elsif KCMU_ABL_KUS_PREFIX_SLIDE_V40
        pf_access_qos_d  <= cmd_kus_adaptive_prefetch_sample ? 3'd7 : cmd_qos;
`elsif KCMU_ABL_KUS_PREFIX_SLIDE_CREDIT_V43
        pf_access_qos_d  <= cmd_kus_special_prefetch_sample ? 3'd7 :
                            (cmd_kus_sliding_prefetch_sample && (cmd_qos < 3'd5)) ? 3'd5 :
                            cmd_qos;
`else
        pf_access_qos_d  <= cmd_qos;
`endif
      end
    end
  end

  kcmu_prefetcher #(
    .ADDR_W(ADDR_W),
    .PREFETCH_QOS_TH(PF_QOS_TH),
    .PF_ADAPT_EN(PF_ADAPT_EN)
`ifdef KCMU_ABL_KUS_PREFIX_SLIDE_CREDIT_V43
    ,
    .USELESS_CREDIT_TH(3),
    .USEFUL_REWARD_STEP(1)
`elsif KCMU_ABL_KUS_MISS_PENALTY_PREFETCH_V47
    ,
    .MISS_CREDIT_TH(4),
    .POLLUTION_CREDIT_TH(8),
    .USEFUL_REWARD_STEP(2)
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_ADAPTIVE_DESC_PREFETCH_V184
    ,
    .USELESS_CREDIT_TH(2),
    .POLLUTION_CREDIT_TH(3),
    .MISS_CREDIT_TH(4),
    .USEFUL_REWARD_STEP(1)
`endif
  ) u_pf (
    .clk(clk),
    .rst_n(rst_n),
    .enable(pf_enable_d),
    .access_fire(pf_access_fire_d),
    .access_addr(pf_access_addr_d),
    .access_qos(pf_access_qos_d),
    .feedback_fill(ex_pf_fill_pulse),
    .feedback_useful(ex_pf_useful_pulse),
    .feedback_demand_miss(ex_demand_miss_pulse),
    .access_miss_penalty_phase(pf_access_miss_penalty_phase_d),
    .hbm_congested(hbm_if_prefetch_block),
    .pf_valid(pf_valid_main),
    .pf_ready(pf_ready_main),
    .pf_addr(pf_addr_main)
  );

  assign pf_demand_preempt_block =
    TRUE_H2O_PREFETCH_DEMAND_PREEMPT_EN &&
    (cmd_valid || cmdq_valid || (cmdq_level != {CMDQ_W{1'b0}}));
  assign pf_demand_preempt_drop =
    TRUE_H2O_PREFETCH_DEMAND_PREEMPT_EN &&
    pf_valid_main &&
    pf_demand_preempt_block;

`ifdef KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_NSA_PREFETCH_V247
  logic [ADDR_W:0] v247_block_stride_ext;
  logic [ADDR_W:0] v247_cmd_next1_addr_ext;
  logic [ADDR_W:0] v247_cmd_next2_addr_ext;
  logic [ADDR_W:0] v247_next1_addr_ext;
  logic [ADDR_W:0] v247_next2_addr_ext;
  logic [31:0]     v247_global_useful_x3;
  logic [31:0]     v247_global_pollution;
  logic [5:0]      v247_epoch_useful_x3;
  wire             v247_token_forward =
    v247_seen_read &&
    ((cmd_token_block_oracle[6:0] == (v247_last_token_block + 7'd1)) ||
     (cmd_token_block_oracle[6:0] == (v247_last_token_block + 7'd2)));
  wire             v247_token_near =
    v247_seen_read &&
    ((cmd_token_block_oracle[6:0] == v247_last_token_block) ||
     (cmd_token_block_oracle[6:0] == (v247_last_token_block + 7'd1)) ||
     (cmd_token_block_oracle[6:0] == (v247_last_token_block + 7'd2)) ||
     (v247_last_token_block == (cmd_token_block_oracle[6:0] + 7'd1)) ||
     (v247_last_token_block == (cmd_token_block_oracle[6:0] + 7'd2)));
  wire             v247_stream_detected = (v247_stream_conf >= 3'd2);
  wire             v247_mixed_nsa_hint =
    (cmd_query_structure_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(2)) ||
    ((cmd_temporal_persist_class >= kcmu_pkg::KCMU_DESC_CLASS_W'(1)) &&
     (cmd_reuse_distance_class <= kcmu_pkg::KCMU_DESC_CLASS_W'(2)));
  wire             v247_backend_ok =
    !hbm_if_prefetch_block &&
    !hbm_if_congested &&
    (hbm_if_q_level < PF_HBM_Q_GUARD_TH);
  wire             v247_miss_credit_ok = (true_h2o_pf_miss_credit >= 3'd4);
  wire             v247_global_useful_ok =
    (stat_prefetch_accept_cnt < 32'd8) ||
    (v247_global_useful_x3 >= stat_prefetch_accept_cnt);
  wire             v247_global_pollution_ok =
    (stat_prefetch_fill_cnt <= stat_prefetch_useful_cnt) ||
    (v247_global_pollution <= (stat_prefetch_fill_cnt >> 2));
  wire             v247_epoch_good =
    (v247_epoch_accept_cnt < 4'd4) ||
    ((v247_epoch_useful_x3 >= {2'b00, v247_epoch_accept_cnt}) &&
     (v247_epoch_pollution_cnt <= 4'd1));
  wire             v247_k2_enable =
    v247_mixed_nsa_hint &&
    (v247_good_epoch_streak == 2'd2) &&
    v247_global_useful_ok &&
    v247_global_pollution_ok;
  wire             v247_trigger =
    cmd_fire_read &&
    !v247_disabled &&
    !v247_pf_pending &&
    (v247_stream_detected || ex_demand_miss_pulse) &&
    v247_miss_credit_ok &&
    v247_backend_ok &&
    v247_global_useful_ok &&
    v247_global_pollution_ok &&
    !pf_demand_preempt_block &&
    !v247_cmd_next1_addr_ext[ADDR_W];

  assign v247_block_stride_ext = ({{ADDR_W{1'b0}}, 1'b1} << KV_BLOCK_OFF_BITS);
  assign v247_cmd_next1_addr_ext = {1'b0, cmd_addr} + v247_block_stride_ext;
  assign v247_cmd_next2_addr_ext = {1'b0, cmd_addr} + (v247_block_stride_ext << 1);
  assign v247_next1_addr_ext = {1'b0, v247_pf_base_addr} + v247_block_stride_ext;
  assign v247_next2_addr_ext = {1'b0, v247_pf_base_addr} + (v247_block_stride_ext << 1);
  assign v247_pf_addr = (v247_pf_idx == 2'd0) ?
                        v247_next1_addr_ext[ADDR_W-1:0] :
                        v247_next2_addr_ext[ADDR_W-1:0];
  assign v247_global_useful_x3 =
    stat_prefetch_useful_cnt + (stat_prefetch_useful_cnt << 1);
  assign v247_global_pollution =
    (stat_prefetch_fill_cnt > stat_prefetch_useful_cnt) ?
      (stat_prefetch_fill_cnt - stat_prefetch_useful_cnt) : 32'd0;
  assign v247_epoch_useful_x3 =
    {2'b00, v247_epoch_useful_cnt} + {1'b0, v247_epoch_useful_cnt, 1'b0};
  assign v247_pf_ready =
    pf_ready &&
    !pf_valid_main &&
    !pf_demand_preempt_block &&
    v247_backend_ok;
  assign v247_pf_issue = v247_pf_pending && v247_pf_ready;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      v247_last_token_block      <= 7'd0;
      v247_stream_conf           <= 3'd0;
      v247_seen_read             <= 1'b0;
      v247_pf_pending            <= 1'b0;
      v247_pf_idx                <= 2'd0;
      v247_pf_limit              <= 2'd1;
      v247_pf_base_addr          <= {ADDR_W{1'b0}};
      v247_epoch_accept_cnt      <= 4'd0;
      v247_epoch_useful_cnt      <= 4'd0;
      v247_epoch_pollution_cnt   <= 4'd0;
      v247_pf_outstanding_cnt    <= 4'd0;
      v247_good_epoch_streak     <= 2'd0;
      v247_disabled              <= 1'b0;
      stat_v247_pf_req_cnt       <= 32'd0;
      stat_v247_pf_useful_cnt    <= 32'd0;
      stat_v247_pf_pollution_cnt <= 32'd0;
      stat_v247_detect_cnt       <= 32'd0;
      stat_v247_stream_cnt       <= 32'd0;
      stat_v247_blocked_cnt      <= 32'd0;
      stat_v247_k2_cnt           <= 32'd0;
      stat_v247_disabled_cnt     <= 32'd0;
    end else begin
      if (cmd_fire_read) begin
        v247_seen_read <= 1'b1;
        if (v247_token_forward) begin
          v247_stream_conf <= (v247_stream_conf == 3'd7) ?
                              3'd7 : (v247_stream_conf + 3'd1);
        end else if (!v247_token_near && (v247_stream_conf != 3'd0)) begin
          v247_stream_conf <= v247_stream_conf - 3'd1;
        end
        v247_last_token_block <= cmd_token_block_oracle[6:0];
      end

      if (cmd_fire_read && v247_stream_detected) begin
        stat_v247_stream_cnt <= stat_v247_stream_cnt + 32'd1;
      end
      if (cmd_fire_read && !v247_disabled && !v247_pf_pending &&
          (v247_stream_detected || ex_demand_miss_pulse) && !v247_trigger) begin
        stat_v247_blocked_cnt <= stat_v247_blocked_cnt + 32'd1;
      end

      if (v247_trigger) begin
        v247_pf_pending   <= 1'b1;
        v247_pf_idx       <= 2'd0;
        v247_pf_limit     <= (v247_k2_enable && !v247_cmd_next2_addr_ext[ADDR_W]) ?
                              2'd2 : 2'd1;
        v247_pf_base_addr <= cmd_addr;
        stat_v247_detect_cnt <= stat_v247_detect_cnt + 32'd1;
        if (v247_k2_enable && !v247_cmd_next2_addr_ext[ADDR_W]) begin
          stat_v247_k2_cnt <= stat_v247_k2_cnt + 32'd1;
        end
      end

      if (v247_pf_issue) begin
        stat_v247_pf_req_cnt <= stat_v247_pf_req_cnt + 32'd1;
        if (v247_pf_outstanding_cnt != 4'hf) begin
          v247_pf_outstanding_cnt <= v247_pf_outstanding_cnt + 4'd1;
        end
        if (v247_epoch_accept_cnt != 4'hf) begin
          v247_epoch_accept_cnt <= v247_epoch_accept_cnt + 4'd1;
        end
        if ((v247_pf_idx + 2'd1) >= v247_pf_limit) begin
          v247_pf_pending <= 1'b0;
          v247_pf_idx <= 2'd0;
        end else begin
          v247_pf_idx <= v247_pf_idx + 2'd1;
        end
      end

      if (ex_pf_useful_pulse && (v247_pf_outstanding_cnt != 4'd0)) begin
        stat_v247_pf_useful_cnt <= stat_v247_pf_useful_cnt + 32'd1;
        v247_pf_outstanding_cnt <= v247_pf_outstanding_cnt - 4'd1;
        if (v247_epoch_useful_cnt != 4'hf) begin
          v247_epoch_useful_cnt <= v247_epoch_useful_cnt + 4'd1;
        end
      end else if (ex_pf_fill_pulse && (v247_pf_outstanding_cnt != 4'd0)) begin
        stat_v247_pf_pollution_cnt <= stat_v247_pf_pollution_cnt + 32'd1;
        v247_pf_outstanding_cnt <= v247_pf_outstanding_cnt - 4'd1;
        if (v247_epoch_pollution_cnt != 4'hf) begin
          v247_epoch_pollution_cnt <= v247_epoch_pollution_cnt + 4'd1;
        end
      end

      if (v247_epoch_accept_cnt >= 4'd8) begin
        if (v247_epoch_good) begin
          v247_good_epoch_streak <= (v247_good_epoch_streak == 2'd2) ?
                                    2'd2 : (v247_good_epoch_streak + 2'd1);
        end else begin
          v247_good_epoch_streak <= 2'd0;
        end
        v247_epoch_accept_cnt    <= 4'd0;
        v247_epoch_useful_cnt    <= 4'd0;
        v247_epoch_pollution_cnt <= 4'd0;
      end

      if ((stat_v247_pf_req_cnt >= 32'd32) &&
          ((stat_v247_pf_useful_cnt + (stat_v247_pf_useful_cnt << 1)) <
           stat_v247_pf_req_cnt)) begin
        v247_disabled <= 1'b1;
      end
      if (v247_disabled) begin
        stat_v247_disabled_cnt <= stat_v247_disabled_cnt + 32'd1;
      end
    end
  end
`endif

`ifdef KCMU_ABL_KUS_TOKEN_PREFETCH_V140
  assign pf_valid = pf_valid_main || v140_pf_issue;
  assign pf_addr = pf_valid_main ? pf_addr_main : v140_pf_addr;
  assign pf_ready_main = pf_ready && pf_valid_main;
`elsif KCMU_CFG_FPGA_H2O_PLUS_SERVICE_CVR_NSA_PREFETCH_V247
  assign pf_valid = (pf_valid_main && !pf_demand_preempt_block) ||
                    (v247_pf_pending && v247_backend_ok && !pf_demand_preempt_block);
  assign pf_addr = (pf_valid_main && !pf_demand_preempt_block) ?
