  assign cmd_kiloscore_qsig_query =
    cmd_sig_valid ? cmd_query_sig :
      (cmd_query_relevance[SCORE_W-1 -: 6] ^
       cmd_service_criticality[SCORE_W-1 -: 6] ^
       {cmd_layer[1:0], cmd_head, cmd_phase, cmd_kv_kind});
  assign cmd_kiloscore_qsig_key =
    cmd_sig_valid ? cmd_key_sig :
      (cmd_attn_score[SCORE_W-1 -: 6] ^
       cmd_token_block_oracle[5:0] ^
       {cmd_token_block_oracle[8:6], cmd_budget_class, cmd_policy_select_s5_active});
  assign cmd_kiloscore_qsig_dist = popcount6(cmd_kiloscore_qsig_query ^ cmd_kiloscore_qsig_key);
