      3'd0: cmd_kiloscore_qsig_bucket_raw = 3'd3;
      3'd1: cmd_kiloscore_qsig_bucket_raw = 3'd3;
      3'd2: cmd_kiloscore_qsig_bucket_raw = 3'd2;
      3'd3: cmd_kiloscore_qsig_bucket_raw = 3'd1;
      default: cmd_kiloscore_qsig_bucket_raw = 3'd0;
