`ifdef KCMU_V409_DEBUG
  always_ff @(posedge clk) begin
    if (rst_n &&
        ((l2_re && (l2_raddr >= ADDR_W'(48)) && (l2_raddr <= ADDR_W'(120))) ||
         (l2_rvalid && (l2_rdata != {DATA_W{1'b0}})))) begin
      $display("V409_MCU_L2_IF re=%0d raddr=%0d rhit=%0d rvalid=%0d rdata=%h rlossy=%0d accepted=%0d time=%0t",
               l2_re,
               l2_raddr,
               l2_rhit,
               l2_rvalid,
               l2_rdata,
               l2_rlossy,
               l2_mem_req_accepted,
               $time);
    end
  end
`endif

  kcmu_backend_ctrl #(
    .ADDR_W(ADDR_W),
    .DATA_W(DATA_W),
    .Q_DEPTH(HBM_IF_Q_DEPTH),
    .SERVICE_CYCLES(HBM_IF_SERVICE_CYCLES),
