    .stat_hbmif_burst_merge_cnt_o(stat_hbmif_burst_merge_cnt),
    .stat_hbmif_wr_drain_cycle_cnt_o(stat_hbmif_wr_drain_cycle_cnt)
  );

  // Synthesizable research-IP observability counters. These are deliberately
  // off the scoring/replacement path and only sample existing handshake pulses.
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      stat_l2_demand_hit_cnt <= 32'd0;
      stat_l2_demand_miss_cnt <= 32'd0;
      stat_prefetch_accept_cnt <= 32'd0;
      stat_prefetch_fill_cnt <= 32'd0;
      stat_prefetch_useful_cnt <= 32'd0;
      stat_backend_stall_cycle_cnt <= 32'd0;
      stat_backend_queue_full_cycle_cnt <= 32'd0;
      true_h2o_pf_miss_credit <= 3'd1;
      true_h2o_pf_budget_read_cnt <= 5'd0;
      true_h2o_pf_budget_issue_cnt <= 3'd0;
      true_h2o_pf_phase_read_cnt <= 6'd0;
      true_h2o_pf_phase_write_cnt <= 8'd0;
      true_h2o_pf_phase_hhonly_cnt <= 5'd0;
      true_h2o_pf_useful_credit <= TRUE_H2O_PREFETCH_USEFUL_ACCEPT_DEBIT_EN ? 3'd7 : 3'd3;
      true_h2o_recent_valid_credit <= 4'd2;
      true_h2o_l2_reuse_valid <= 1'b0;
      true_h2o_l2_reuse_addr <= {ADDR_W{1'b0}};
      true_h2o_l2_reuse_credit <= 2'd0;
    end else begin
      if (l2_re && !l2_req_prefetch) begin
        if (l2_rhit) begin
          stat_l2_demand_hit_cnt <= stat_l2_demand_hit_cnt + 32'd1;
        end else begin
          stat_l2_demand_miss_cnt <= stat_l2_demand_miss_cnt + 32'd1;
        end
      end

      if (pf_valid && pf_ready) begin
        stat_prefetch_accept_cnt <= stat_prefetch_accept_cnt + 32'd1;
      end
      if (ex_pf_fill_pulse) begin
        stat_prefetch_fill_cnt <= stat_prefetch_fill_cnt + 32'd1;
      end
      if (ex_pf_useful_pulse) begin
        stat_prefetch_useful_cnt <= stat_prefetch_useful_cnt + 32'd1;
      end

      if ((l2_mem_re && !l2_mem_re_ready) || (l2_mem_we && !l2_mem_we_ready)) begin
        stat_backend_stall_cycle_cnt <= stat_backend_stall_cycle_cnt + 32'd1;
      end
      if (hbm_if_q_level >= HBM_Q_W'(HBM_IF_Q_DEPTH)) begin
        stat_backend_queue_full_cycle_cnt <= stat_backend_queue_full_cycle_cnt + 32'd1;
      end

      if (!TRUE_H2O_PREFETCH_USEFUL_CREDIT_EN) begin
        true_h2o_pf_useful_credit <= TRUE_H2O_PREFETCH_USEFUL_ACCEPT_DEBIT_EN ? 3'd7 : 3'd3;
      end else if (ex_pf_useful_pulse) begin
        if (true_h2o_pf_useful_credit >= 3'd5) begin
          true_h2o_pf_useful_credit <= 3'd7;
        end else begin
          true_h2o_pf_useful_credit <= true_h2o_pf_useful_credit + 3'd2;
        end
      end else if (((TRUE_H2O_PREFETCH_USEFUL_ACCEPT_DEBIT_EN && pf_valid && pf_ready) ||
                    (!TRUE_H2O_PREFETCH_USEFUL_ACCEPT_DEBIT_EN && ex_pf_fill_pulse)) &&
                   (true_h2o_pf_useful_credit != 3'd0)) begin
        true_h2o_pf_useful_credit <= true_h2o_pf_useful_credit - 3'd1;
      end

      if (!TRUE_H2O_PREFETCH_BUDGET_EN) begin
        true_h2o_pf_budget_read_cnt <= 5'd0;
        true_h2o_pf_budget_issue_cnt <= 3'd0;
      end else begin
        if (cmd_fire_read) begin
          if (true_h2o_pf_budget_read_cnt == 5'd31) begin
            true_h2o_pf_budget_read_cnt <= 5'd0;
            true_h2o_pf_budget_issue_cnt <= 3'd0;
          end else begin
            true_h2o_pf_budget_read_cnt <= true_h2o_pf_budget_read_cnt + 5'd1;
          end
        end
        if (pf_valid && pf_ready) begin
          if (true_h2o_pf_budget_epoch_wrap) begin
            true_h2o_pf_budget_issue_cnt <= 3'd1;
          end else if (true_h2o_pf_budget_issue_cnt != 3'd7) begin
            true_h2o_pf_budget_issue_cnt <= true_h2o_pf_budget_issue_cnt + 3'd1;
          end
        end
      end

      if (!TRUE_H2O_PREFETCH_WRDOM_HHONLY_GATE_EN) begin
        true_h2o_pf_phase_read_cnt <= 6'd0;
        true_h2o_pf_phase_write_cnt <= 8'd0;
        true_h2o_pf_phase_hhonly_cnt <= 5'd0;
      end else begin
        if (cmd_fire_read && (true_h2o_pf_phase_read_cnt != 6'h3f)) begin
          true_h2o_pf_phase_read_cnt <= true_h2o_pf_phase_read_cnt + 6'd1;
        end
        if (cmd_fire_write && (true_h2o_pf_phase_write_cnt != 8'hff)) begin
          true_h2o_pf_phase_write_cnt <= true_h2o_pf_phase_write_cnt + 8'd1;
        end
        if (cmd_fire_read &&
            cmd_attn_h2o_en &&
            (cmd_h2o_class_policy == kcmu_pkg::KCMU_H2O_HEAVY_ONLY) &&
            (true_h2o_pf_phase_hhonly_cnt != 5'h1f)) begin
          true_h2o_pf_phase_hhonly_cnt <= true_h2o_pf_phase_hhonly_cnt + 5'd1;
        end
      end

      if (!TRUE_H2O_RECENT_VALID_SERVICE_EN) begin
        true_h2o_recent_valid_credit <= 4'd2;
      end else if (l2_re && !l2_req_prefetch && l2_req_recent_keep) begin
        if (l2_rhit) begin
          if (true_h2o_recent_valid_credit != 4'hf) begin
            true_h2o_recent_valid_credit <= true_h2o_recent_valid_credit + 4'd1;
          end
        end else if (true_h2o_recent_valid_credit != 4'd0) begin
          true_h2o_recent_valid_credit <= true_h2o_recent_valid_credit - 4'd1;
        end
      end

      if (!TRUE_H2O_L2_REUSE_PROMOTE_EN) begin
        true_h2o_l2_reuse_valid <= 1'b0;
        true_h2o_l2_reuse_addr <= {ADDR_W{1'b0}};
        true_h2o_l2_reuse_credit <= 2'd0;
      end else if (l2_re && !l2_req_prefetch) begin
        if (l2_rhit) begin
          if (true_h2o_l2_reuse_valid && (true_h2o_l2_reuse_addr == l2_raddr)) begin
            if (true_h2o_l2_reuse_credit != 2'd3) begin
              true_h2o_l2_reuse_credit <= true_h2o_l2_reuse_credit + 2'd1;
            end
          end else begin
            true_h2o_l2_reuse_valid <= 1'b1;
            true_h2o_l2_reuse_addr <= l2_raddr;
            true_h2o_l2_reuse_credit <= 2'd1;
          end
        end else if (true_h2o_l2_reuse_valid && (true_h2o_l2_reuse_addr == l2_raddr)) begin
          if (true_h2o_l2_reuse_credit <= 2'd1) begin
            true_h2o_l2_reuse_valid <= 1'b0;
            true_h2o_l2_reuse_credit <= 2'd0;
          end else begin
            true_h2o_l2_reuse_credit <= true_h2o_l2_reuse_credit - 2'd1;
          end
        end
      end

      if (true_h2o_pf_miss_credit_gate_active) begin
        unique case ({(l2_re && !l2_req_prefetch && !l2_rhit), (pf_valid && pf_ready)})
          2'b10: begin
            if (true_h2o_pf_miss_credit != 3'd7) begin
              true_h2o_pf_miss_credit <= true_h2o_pf_miss_credit + 3'd1;
            end
          end
          2'b01: begin
            if (true_h2o_pf_miss_credit != 3'd0) begin
              true_h2o_pf_miss_credit <= true_h2o_pf_miss_credit - 3'd1;
            end
          end
          default: begin
            true_h2o_pf_miss_credit <= true_h2o_pf_miss_credit;
          end
        endcase
      end else begin
        true_h2o_pf_miss_credit <= 3'd7;
      end
    end
  end

  // Execute
  kcmu_execute #(
    .ADDR_W(ADDR_W),
    .DATA_W(DATA_W),
    .LINES(LINES),
    .SCORE_W(SCORE_W),
    .TIME_W(TIME_W),
    .K_RECENT(K_RECENT),
    .H2O_V2_EN(KCMU_POLICY_SCORE_PATH_EN),
    .UTILITY_SCORE_REPL_EN(UTILITY_SCORE_REPL_EN),
    .QMATCH_RECENT_COLD_TIEBREAK_EN(QMATCH_RECENT_COLD_TIEBREAK_EN),
    .QMATCH_L1_QUERY_SEED_EN(QMATCH_L1_QUERY_SEED_EN),
    .QMATCH_L1_KEEP_TIEBREAK_EN(QMATCH_L1_KEEP_TIEBREAK_EN),
    .HBM_Q_W(HBM_Q_W),
    .MEM_RD_LATENCY(MEM_RD_LATENCY),
    .L2_RD_LATENCY(L2_RD_LATENCY),
    .HIER_POLICY_EN(HIER_POLICY_EN),
    .L1_BYPASS_QOS_TH(L1_BYPASS_QOS_TH),
    .L1_DEMAND_FILL_QOS_TH(L1_DEMAND_FILL_QOS_TH),
    .L1_PREFETCH_FILL_QOS_TH(L1_PREFETCH_FILL_QOS_TH),
    .L1_MISS_BYPASS_QOS_TH(L1_MISS_BYPASS_QOS_TH),
    .L1_CONGEST_BYPASS_QOS_TH(L1_CONGEST_BYPASS_QOS_TH),
    .PREFETCH_CONGEST_QOS_TH(PREFETCH_CONGEST_QOS_TH),
    .PREFETCH_HBM_ISSUE_QOS_TH(PREFETCH_HBM_ISSUE_QOS_TH),
    .PREFETCH_HBM_ISSUE_RELAX_HOT(PREFETCH_HBM_ISSUE_RELAX_HOT),
    .EXEC_CONGEST_Q_LEVEL_TH(EXEC_CONGEST_Q_LEVEL_TH),
    .HBM_CONGEST_COLD_EXTRA_LAT(HBM_CONGEST_COLD_EXTRA_LAT),
    .HBM_CONGEST_HOT_EXTRA_LAT(HBM_CONGEST_HOT_EXTRA_LAT),
    .HBM_CONGEST_PREFETCH_EXTRA_LAT(HBM_CONGEST_PREFETCH_EXTRA_LAT),
    .L1_FILL_ON_HBM_MISS(L1_FILL_ON_HBM_MISS),
    .L2_HIT_REUSE_BUFFER_EN(L2_HIT_REUSE_BUFFER_EN),
    .L2_HIT_REUSE_BUFFER_DEPTH(L2_HIT_REUSE_BUFFER_DEPTH),
    .LINE_IDX_W(LINE_IDX_W)
  ) u_ex (
    .clk(clk),
    .rst_n(rst_n),

    .cmd_valid(cmd_valid),
    .cmd_ready(cmd_ready),
    .cmd_op(cmd_op),
    .cmd_addr(cmd_addr_exec),
    .cmd_wdata(cmd_wdata),
    .cmd_qos(cmd_exec_qos),
    .cmd_sem_hot(cmd_sem_hot),
    .cmd_fill_allow(cmd_true_fill_allow),
    .cmd_victim_protect(cmd_true_victim_protect),
    .cmd_compress_allow(cmd_compress_allow),
    .cmd_hh_protect(cmd_policy_score_en && cmd_hh_retention_protect),
    .cmd_recent_keep(cmd_policy_score_en && cmd_recent_keep_policy),
    .cmd_h2o_class(cmd_policy_score_en ? cmd_h2o_class_retention_policy : kcmu_pkg::KCMU_H2O_NEITHER),
    .cmd_l1_hh_protect(cmd_policy_score_en && cmd_hh_l1_retention_protect),
    .cmd_l1_h2o_class(cmd_policy_score_en ? cmd_h2o_class_l1_retention_policy : kcmu_pkg::KCMU_H2O_NEITHER),
    .cmd_utility_score(cmd_utility_en ? cmd_utility_score : {SCORE_W{1'b0}}),
    .cmd_query_relevance((cmd_utility_en || cmd_hasp_lrrb_l2_candidate) ?
                         cmd_query_relevance_l2_eff : {SCORE_W{1'b0}}),
    .cmd_head_budget_class(cmd_head_budget_class),
    .cmd_temporal_persist_class(cmd_temporal_persist_class),
    .cmd_reuse_distance_class(cmd_reuse_distance_class),
    .cmd_query_structure_class(cmd_query_structure_class),
    .cmd_marginal_active(cmd_policy_select_s5_active),
    .cmd_service_issue_boost(cmd_service_issue_boost),
    .cmd_sched_query_take(cmd_sched_query_take && !cmd_sched_safe_haqu_floor_active),
    .cmd_sched_temporal_take(cmd_sched_temporal_take && !cmd_sched_safe_haqu_floor_active),
    .cmd_sched_query_bias_take(cmd_sched_l2_query_bias_take && !cmd_sched_safe_haqu_floor_active),
    .cmd_kv_sibling_keep(cmd_kus_kv_sibling_keep),
    .cmd_block_last(cmd_block_last),
    .cmd_group_target_valid(cmd_group_target_valid_eff),
    .cmd_group_target_addr(cmd_group_target_addr),
    .cmd_group_v251gf_force(cmd_group_v251gf_force),
    .cmd_kiloscore_extra_cvr_hint(cmd_kiloscore_extra_cvr_hint),
    .cmd_kiloscore_qsig_bucket(cmd_kiloscore_qsig_bucket),

    .pf_valid(pf_valid),
    .pf_ready(pf_ready),
    .pf_addr(pf_addr),
    .pf_qos(pf_qos),
    .pf_sem_hot(pf_sem_hot),
    .pf_fill_allow(pf_fill_allow),
    .pf_victim_protect(pf_victim_protect),
    .pf_compress_allow(pf_compress_allow),
    .pf_hh_protect(pf_hh_protect),
    .pf_recent_keep(pf_recent_keep),
    .pf_h2o_class(pf_h2o_class),
    .pf_utility_score({SCORE_W{1'b0}}),
    .pf_query_relevance({SCORE_W{1'b0}}),
    .pf_fill_pulse(ex_pf_fill_pulse),
    .pf_useful_pulse(ex_pf_useful_pulse),

    .resp_valid(resp_valid),
    .resp_ready(resp_ready),
    .resp_rdata(resp_rdata),
    .resp_hit(resp_hit),
    .resp_approx(resp_approx),

    .sram_re(sram_re),
    .sram_raddr(sram_raddr),
    .sram_rdata(sram_rdata),
    .sram_we(sram_we),
    .sram_waddr(sram_waddr),
    .sram_wdata(sram_wdata),

    .mem_re(l2_re),
    .mem_raddr(l2_raddr),
    .mem_req_prefetch(l2_req_prefetch),
    .mem_req_qos(l2_req_qos),
    .mem_req_sem_hot(l2_req_sem_hot),
    .mem_req_fill_allow(l2_req_fill_allow),
    .mem_req_victim_protect(l2_req_victim_protect),
    .mem_req_compress_allow(l2_req_compress_allow),
    .mem_req_hh_protect(l2_req_hh_protect),
    .mem_req_recent_keep(l2_req_recent_keep),
    .mem_req_h2o_class(l2_req_h2o_class),
    .mem_req_utility_score(l2_req_utility_score),
    .mem_req_query_relevance(l2_req_query_relevance),
    .mem_req_head_budget_class(l2_req_head_budget_class),
    .mem_req_temporal_persist_class(l2_req_temporal_persist_class),
    .mem_req_reuse_distance_class(l2_req_reuse_distance_class),
    .mem_req_query_structure_class(l2_req_query_structure_class),
    .mem_req_marginal_active(l2_req_marginal_active),
    .mem_req_service_issue_boost(l2_req_service_issue_boost),
    .mem_req_sched_query_take(l2_req_sched_query_take),
    .mem_req_sched_temporal_take(l2_req_sched_temporal_take),
    .mem_req_sched_query_bias_take(l2_req_sched_query_bias_take),
    .mem_req_block_last(l2_req_block_last),
    .mem_req_group_target_valid(l2_req_group_target_valid),
    .mem_req_group_target_addr(l2_req_group_target_addr),
    .mem_req_group_v251gf_force(l2_req_group_v251gf_force),
    .mem_req_kiloscore_extra_cvr_hint(l2_req_kiloscore_extra_cvr_hint),
    .mem_req_kiloscore_qsig_bucket(l2_req_kiloscore_qsig_bucket),
    .mem_rdata(l2_rdata),
    .mem_rvalid(l2_rvalid),
    .mem_l2_hit(l2_rhit),
    .mem_rsource(l2_rsource),
    .mem_req_accepted(l2_mem_req_accepted),
    .mem_r_lossy(l2_rlossy),
    .hbm_q_level(hbm_if_q_level),
    .hbm_congested(hbm_if_congested),
    .hbm_prefetch_block(hbm_if_prefetch_block),

    .mem_we(l2_we),
    .mem_waddr(l2_waddr),
    .mem_wdata(l2_wdata),
    .stat_demand_req_cnt(stat_demand_req_cnt),
    .stat_demand_miss_cnt(stat_demand_miss_cnt),
    .stat_miss_rate_permille(stat_miss_rate_permille)
  );

endmodule

